// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

type Link<T> = Option<NonNull<Node<T>>>;

struct Node<T> {
    elem: T,
    prev: Link<T>,
    next: Link<T>,
}

/// Invariants:
/// - every node pointer reachable from `head`/`tail` was created by `Box::into_raw`
///   and is owned exclusively by this list.
/// - `head`/`tail` are `None` iff `len == 0`.
/// - node links are consistent (a.next == b <=> b.prev == a).
pub struct LinkedList<T> {
    head: Link<T>,
    tail: Link<T>,
    len: usize,
    // NonNull is covariant; PhantomData signals ownership of T for drop check.
    _marker: PhantomData<Box<Node<T>>>,
}

pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    cur: Link<T>,
}

pub struct Iter<'a, T> {
    next: Link<T>,
    _marker: PhantomData<&'a T>,
}

// SAFETY: the list owns its Ts exclusively, like Vec<T>/Box<T>.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: &LinkedList only gives out &T.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

impl<T> Default for LinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let cur = self.head;
        Cursor { list: self, cur }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let cur = self.tail;
        Cursor { list: self, cur }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.head,
            _marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut c = self.cursor_front();
        while c.take().is_some() {}
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: cur is a valid node owned by the list, which we borrow mutably;
        // the returned borrow is tied to &mut self.
        self.cur.map(|n| unsafe { &mut (*n.as_ptr()).elem })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let cur = self.cur?;
        // SAFETY: cur is a valid node of the list.
        let next = unsafe { (*cur.as_ptr()).next };
        next?;
        self.cur = next;
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let cur = self.cur?;
        // SAFETY: cur is a valid node of the list.
        let prev = unsafe { (*cur.as_ptr()).prev };
        prev?;
        self.cur = prev;
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let cur = self.cur?;
        // SAFETY: cur was created by Box::into_raw and is owned by the list.
        // We unlink it, fixing neighbours (valid nodes) and head/tail, then
        // reclaim the box exactly once.
        unsafe {
            let node = Box::from_raw(cur.as_ptr());
            match node.prev {
                Some(p) => (*p.as_ptr()).next = node.next,
                None => self.list.head = node.next,
            }
            match node.next {
                Some(n) => (*n.as_ptr()).prev = node.prev,
                None => self.list.tail = node.prev,
            }
            self.list.len -= 1;
            self.cur = node.next.or(node.prev);
            Some(node.elem)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        let new = Box::new(Node {
            elem: element,
            prev: self.cur,
            next: None,
        });
        match self.cur {
            None => {
                let ptr = NonNull::from(Box::leak(new));
                self.list.head = Some(ptr);
                self.list.tail = Some(ptr);
                self.cur = Some(ptr);
            }
            Some(cur) => {
                // SAFETY: cur and its next (if any) are valid nodes of the list;
                // we link the new node consistently between them.
                unsafe {
                    let next = (*cur.as_ptr()).next;
                    let mut new = new;
                    new.next = next;
                    let ptr = NonNull::from(Box::leak(new));
                    (*cur.as_ptr()).next = Some(ptr);
                    match next {
                        Some(n) => (*n.as_ptr()).prev = Some(ptr),
                        None => self.list.tail = Some(ptr),
                    }
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new = Box::new(Node {
            elem: element,
            prev: None,
            next: self.cur,
        });
        match self.cur {
            None => {
                let ptr = NonNull::from(Box::leak(new));
                self.list.head = Some(ptr);
                self.list.tail = Some(ptr);
                self.cur = Some(ptr);
            }
            Some(cur) => {
                // SAFETY: cur and its prev (if any) are valid nodes of the list;
                // we link the new node consistently between them.
                unsafe {
                    let prev = (*cur.as_ptr()).prev;
                    let mut new = new;
                    new.prev = prev;
                    let ptr = NonNull::from(Box::leak(new));
                    (*cur.as_ptr()).prev = Some(ptr);
                    match prev {
                        Some(p) => (*p.as_ptr()).next = Some(ptr),
                        None => self.list.head = Some(ptr),
                    }
                }
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let n = self.next?;
        // SAFETY: the list is immutably borrowed for 'a, so nodes stay valid
        // and unmodified for 'a.
        unsafe {
            let node = &*n.as_ptr();
            self.next = node.next;
            Some(&node.elem)
        }
    }
}
```

Below is the full implementation of the doubly linked list in `src/lib.rs`, covering all five steps.

**Structure**
- Nodes are allocated with `Box` and turned into `NonNull<Node<T>>` raw pointers.
- `LinkedList` stores `head`, `tail` and `len`, so `len()` and `is_empty()` are cheap.
- It also holds a `PhantomData<Box<Node<T>>>` marker. This tells the compiler (drop check) that the list owns `T` values.

**Covariance**
- `Option<NonNull<Node<T>>>` and `PhantomData<Box<Node<T>>>` are both covariant over `T`.
- So `LinkedList<T>` is covariant over `T`.

**Cursor**
- The cursor holds `&mut LinkedList<T>` and an optional pointer to the current node.
- `next` and `prev` only move if a neighbor exists. Otherwise they return `None` and stay on the current element.
- `take` unlinks the current node and moves the cursor to the next node. If there is no next node, it moves to the previous one.
- Inserting into an empty list makes the new node both head and tail. The cursor then points at it.

**Drop**
- Removes every element with a front cursor's `take`, as the instructions ask (all changes go through the cursor).

**Send / Sync**
- Implemented manually, with the same bounds `std` uses for `Box<T>` / `Vec<T>`.

**Safety**
- The safety invariants are written at the top of the file, and each `unsafe` block has a comment explaining why it is sound.

