// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

// Safety-critical invariants of `LinkedList<T>`:
//
// 1. Every node reachable from `head` (following `next`) or from `tail`
//    (following `prev`) was allocated by `Box::new` and is owned exclusively
//    by this list. Nodes are only freed by reconstructing the `Box` exactly once
//    when they are removed from the list.
// 2. `head` is `None` iff `tail` is `None` iff `len == 0`.
// 3. For every node `n` in the list: if `n.next == Some(m)` then
//    `m.prev == Some(n)` and vice versa. `head.prev` and `tail.next` are `None`.
// 4. `len` equals the number of nodes in the list.
//
// A `Cursor` holds a unique borrow of the list, so it is the only way to
// access the nodes while it exists. Its `cur` pointer is either `None` (only
// when the list is empty) or points to a node currently in the list.
//
// An `Iter` holds a shared borrow of the list, so no node can be mutated or
// freed while the iterator lives.

type Link<T> = Option<NonNull<Node<T>>>;

struct Node<T> {
    elem: T,
    prev: Link<T>,
    next: Link<T>,
}

pub struct LinkedList<T> {
    head: Link<T>,
    tail: Link<T>,
    len: usize,
    // Signals ownership of `T` values (for drop check) and keeps covariance.
    _marker: PhantomData<Box<Node<T>>>,
}

pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    cur: Link<T>,
}

pub struct Iter<'a, T> {
    next: Link<T>,
    remaining: usize,
    _marker: PhantomData<&'a T>,
}

// SAFETY: The list owns its `T` values exclusively, just like `Box<T>` or
// `Vec<T>`. Sending the list sends the values, which requires `T: Send`.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: `&LinkedList<T>` only allows shared access (`&T`) to the elements,
// which is fine across threads when `T: Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: An `Iter` behaves like `&'a T` items, so it is Send/Sync when `T: Sync`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

// SAFETY: A `Cursor` behaves like `&'a mut LinkedList<T>`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let cur = self.head;
        Cursor { list: self, cur }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let cur = self.tail;
        Cursor { list: self, cur }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.head,
            remaining: self.len,
            _marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cursor = self.cursor_front();
        while cursor.take().is_some() {}
    }
}

/// Allocate a new node on the heap and return an owning raw pointer to it.
fn new_node<T>(elem: T, prev: Link<T>, next: Link<T>) -> NonNull<Node<T>> {
    let boxed = Box::new(Node { elem, prev, next });
    // Box::into_raw never returns null.
    NonNull::from(Box::leak(boxed))
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `cur` points to a live node of the list (invariant), and the
        // cursor holds the unique borrow of the list. The returned reference
        // is tied to `&mut self`, so no aliasing mutable access is possible.
        self.cur.map(|node| unsafe { &mut (*node.as_ptr()).elem })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let cur = self.cur?;
        // SAFETY: `cur` points to a live node of the list.
        let next = unsafe { (*cur.as_ptr()).next };
        match next {
            Some(n) => {
                self.cur = Some(n);
                self.peek_mut()
            }
            None => None,
        }
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let cur = self.cur?;
        // SAFETY: `cur` points to a live node of the list.
        let prev = unsafe { (*cur.as_ptr()).prev };
        match prev {
            Some(p) => {
                self.cur = Some(p);
                self.peek_mut()
            }
            None => None,
        }
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let cur = self.cur?;
        // SAFETY: `cur` was allocated via `Box` and is owned by the list.
        // We unlink it below so that no pointer to it remains in the list,
        // hence reconstructing the Box here frees it exactly once.
        let node = unsafe { Box::from_raw(cur.as_ptr()) };
        let Node { elem, prev, next } = *node;

        match prev {
            // SAFETY: `p` is a live node in the list, distinct from `cur`.
            Some(p) => unsafe { (*p.as_ptr()).next = next },
            None => self.list.head = next,
        }
        match next {
            // SAFETY: `n` is a live node in the list, distinct from `cur`.
            Some(n) => unsafe { (*n.as_ptr()).prev = prev },
            None => self.list.tail = prev,
        }
        self.list.len -= 1;
        self.cur = next.or(prev);
        Some(elem)
    }

    pub fn insert_after(&mut self, element: T) {
        match self.cur {
            None => {
                // Empty list (invariant: cur is None only if the list is empty).
                let node = new_node(element, None, None);
                self.list.head = Some(node);
                self.list.tail = Some(node);
                self.cur = Some(node);
            }
            Some(cur) => {
                // SAFETY: `cur` is a live node in the list; we hold unique access.
                unsafe {
                    let next = (*cur.as_ptr()).next;
                    let node = new_node(element, Some(cur), next);
                    match next {
                        Some(n) => (*n.as_ptr()).prev = Some(node),
                        None => self.list.tail = Some(node),
                    }
                    (*cur.as_ptr()).next = Some(node);
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        match self.cur {
            None => {
                // Empty list (invariant: cur is None only if the list is empty).
                let node = new_node(element, None, None);
                self.list.head = Some(node);
                self.list.tail = Some(node);
                self.cur = Some(node);
            }
            Some(cur) => {
                // SAFETY: `cur` is a live node in the list; we hold unique access.
                unsafe {
                    let prev = (*cur.as_ptr()).prev;
                    let node = new_node(element, prev, Some(cur));
                    match prev {
                        Some(p) => (*p.as_ptr()).next = Some(node),
                        None => self.list.head = Some(node),
                    }
                    (*cur.as_ptr()).prev = Some(node);
                }
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: The iterator borrows the list immutably for `'a`, so the
        // node is live and not mutated for `'a`.
        let node_ref: &'a Node<T> = unsafe { &*node.as_ptr() };
        self.next = node_ref.next;
        self.remaining = self.remaining.saturating_sub(1);
        Some(&node_ref.elem)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}
