// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

/// A (possibly absent) pointer to a node of a [`LinkedList`].
///
/// `NonNull` is used instead of `*mut` because it is covariant over its
/// pointee, which makes `LinkedList<T>` and `Iter<'_, T>` covariant over `T`.
type Link<T> = Option<NonNull<Node<T>>>;

/// A heap allocated node of a [`LinkedList`].
struct Node<T> {
    element: T,
    prev: Link<T>,
    next: Link<T>,
}

/// A doubly linked list.
///
/// # Invariants
///
/// All `unsafe` code in this crate relies on the following invariants, which
/// every operation that modifies the list has to uphold:
///
/// 1. Every node of the list was allocated through a `Box` (which was then
///    leaked) and is exclusively owned by this list. Pointers to it are only
///    stored in the list itself (`front`, `back` and the links of the
///    neighboring nodes), and in `Cursor`s and `Iter`s, which borrow the list.
/// 2. `len` is the number of nodes in the list.
///    `front` and `back` are `None` if and only if the list is empty.
/// 3. The nodes form a proper chain: Following the `next` links from `front`
///    visits every node of the list exactly once and ends at `back`, whose
///    `next` is `None`. The `prev` links mirror that: `a.next == Some(b)`
///    if and only if `b.prev == Some(a)`, and the `prev` of `front` is `None`.
///    In particular, the neighbors of a node of the list are nodes of the
///    list as well, and `front` is the only node without a predecessor.
pub struct LinkedList<T> {
    front: Link<T>,
    back: Link<T>,
    len: usize,
    /// Tells the compiler (in particular the drop checker) that the list owns
    /// its nodes and therefore values of type `T`.
    _marker: PhantomData<Box<Node<T>>>,
}

/// A cursor pointing at an element of a [`LinkedList`], which can move
/// through the list and modify it at its position.
///
/// # Invariants
///
/// `current` is `None` if and only if the list is empty.
/// Otherwise, it points to a node of `list`.
///
/// As the cursor borrows the list mutably, nothing else can access the list
/// or its nodes while the cursor is alive.
pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Link<T>,
}

/// An iterator over the elements of a [`LinkedList`], from front to back.
///
/// # Invariants
///
/// `next_node` is either `None` or points to a node of a list that is
/// immutably borrowed for `'a`. Therefore, that node and all nodes after it
/// stay alive and unmodified for at least `'a`.
pub struct Iter<'a, T> {
    next_node: Link<T>,
    _marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            front: None,
            back: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Returns the number of elements. This is O(1), because the length is
    /// updated on every insertion and removal.
    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        Cursor {
            current: self.front,
            list: self,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        Cursor {
            current: self.back,
            list: self,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next_node: self.front,
            _marker: PhantomData,
        }
    }

    /// Allocates a new node holding `element`, links it in between `prev` and
    /// `next` and returns a pointer to it.
    ///
    /// # Safety
    ///
    /// `prev` and `next` must be adjacent positions of this list, i.e. either
    /// - `prev` is a node of this list and `next` is its `next` link, or
    /// - `prev` is `None` and `next` is `self.front`.
    unsafe fn insert_between(
        &mut self,
        prev: Link<T>,
        next: Link<T>,
        element: T,
    ) -> NonNull<Node<T>> {
        let new = Box::new(Node {
            element,
            prev,
            next,
        });
        let node = NonNull::from(Box::leak(new));

        match prev {
            // SAFETY: `prev` is a node of this list (precondition), so it is
            // valid, and `&mut self` guarantees exclusive access to it.
            Some(prev) => unsafe { (*prev.as_ptr()).next = Some(node) },
            None => self.front = Some(node),
        }
        match next {
            // SAFETY: Given the precondition, `next` is a node of this list as
            // well (invariant 3), and `&mut self` guarantees exclusive access.
            Some(next) => unsafe { (*next.as_ptr()).prev = Some(node) },
            None => self.back = Some(node),
        }
        self.len += 1;
        node
    }

    /// Unlinks `node` from this list, frees its allocation and returns its
    /// contents. The links of the returned node point to its former neighbors.
    ///
    /// # Safety
    ///
    /// `node` must be a node of this list.
    unsafe fn unlink(&mut self, node: NonNull<Node<T>>) -> Node<T> {
        // SAFETY: `node` is a node of this list (precondition), so it was
        // allocated through a `Box` and is exclusively owned by this list
        // (invariant 1). All pointers to it are removed from the list below,
        // so the freed node can't be accessed anymore.
        let removed = unsafe { *Box::from_raw(node.as_ptr()) };

        match removed.prev {
            // SAFETY: The neighbors of a node of this list are nodes of this
            // list (invariant 3), and `&mut self` guarantees exclusive access.
            Some(prev) => unsafe { (*prev.as_ptr()).next = removed.next },
            None => self.front = removed.next,
        }
        match removed.next {
            // SAFETY: same as above
            Some(next) => unsafe { (*next.as_ptr()).prev = removed.prev },
            None => self.back = removed.prev,
        }
        self.len -= 1;
        removed
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: `current` is a node of the list (cursor invariant), so it is
        // valid. The cursor has exclusive access to the list and the returned
        // reference mutably borrows the cursor, so no other reference to the
        // element can exist while it's alive.
        Some(unsafe { &mut (*current.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    ///
    /// If there is no next element, the cursor stays where it is.
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: `current` is a node of the list (cursor invariant), and the
        // cursor has exclusive access to it.
        let next = unsafe { (*current.as_ptr()).next }?;
        // `next` is a node of the list as well (invariant 3).
        self.current = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    ///
    /// If there is no previous element, the cursor stays where it is.
    pub fn prev(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: `current` is a node of the list (cursor invariant), and the
        // cursor has exclusive access to it.
        let prev = unsafe { (*current.as_ptr()).prev }?;
        // `prev` is a node of the list as well (invariant 3).
        self.current = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let current = self.current?;
        // SAFETY: `current` is a node of the list (cursor invariant).
        let removed = unsafe { self.list.unlink(current) };
        // The former neighbors of the removed node are still nodes of the list.
        // If it had none, the list is empty now and the cursor points nowhere.
        self.current = removed.next.or(removed.prev);
        Some(removed.element)
    }

    /// Insert `element` after the current position without moving the cursor.
    /// If the list is empty, the cursor moves onto the inserted element.
    pub fn insert_after(&mut self, element: T) {
        let (prev, next) = match self.current {
            // SAFETY: `current` is a node of the list (cursor invariant), and
            // the cursor has exclusive access to it.
            Some(current) => (Some(current), unsafe { (*current.as_ptr()).next }),
            None => (None, self.list.front),
        };
        // SAFETY: Either `prev` is a node of the list and `next` is its `next`
        // link, or `prev` is `None` and `next` is the front of the list.
        let new = unsafe { self.list.insert_between(prev, next, element) };
        if self.current.is_none() {
            // The list was empty before, so move onto its only element.
            self.current = Some(new);
        }
    }

    /// Insert `element` before the current position without moving the cursor.
    /// If the list is empty, the cursor moves onto the inserted element.
    pub fn insert_before(&mut self, element: T) {
        let (prev, next) = match self.current {
            // SAFETY: `current` is a node of the list (cursor invariant), and
            // the cursor has exclusive access to it.
            Some(current) => (unsafe { (*current.as_ptr()).prev }, Some(current)),
            None => (self.list.back, None),
        };
        // SAFETY: If `prev` is a node of the list, it's the predecessor of
        // `current` or the back of the list, so `next` is its `next` link
        // (invariant 3). If `prev` is `None`, `next` is the front of the list:
        // either `current` has no predecessor, so it is the front (invariant 3),
        // or the list is empty and `next` is `None`, just like the front.
        let new = unsafe { self.list.insert_between(prev, next, element) };
        if self.current.is_none() {
            // The list was empty before, so move onto its only element.
            self.current = Some(new);
        }
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next_node?;
        // SAFETY: `node` is a node of a list that is immutably borrowed for
        // `'a` (iterator invariant), so it stays valid and unmodified for `'a`.
        let node: &'a Node<T> = unsafe { &*node.as_ptr() };
        // `node.next` is either `None` or the next node of the same list
        // (invariant 3), so the iterator invariant is upheld.
        self.next_node = node.next;
        Some(&node.element)
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Remove the elements one after another in a loop.
        // (Dropping the nodes recursively could overflow the stack.)
        let mut cursor = self.cursor_front();
        while cursor.take().is_some() {}
    }
}

// SAFETY: A `LinkedList<T>` exclusively owns its nodes (invariant 1), just
// like a `Vec<T>` owns its buffer. Sending it to another thread only moves
// the `T`s to that thread, which is sound if `T: Send`.
unsafe impl<T: Send> Send for LinkedList<T> {}

// SAFETY: A `&LinkedList<T>` only allows reading the structure of the list
// and obtaining `&T`s, there's no interior mutability. Doing that from
// multiple threads at once is sound if `T: Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: A `Cursor` is semantically a `&mut LinkedList<T>` (plus a position
// in it), so it's `Send`/`Sync` under the same conditions as
// `&mut LinkedList<T>`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: An `Iter` is semantically a `&LinkedList<T>`, which is `Send` and
// `Sync` if `LinkedList<T>: Sync`, i.e. if `T: Sync`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
unsafe impl<T: Sync> Sync for Iter<'_, T> {}
