// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

type Link<T> = Option<NonNull<Node<T>>>;

struct Node<T> {
    elem: T,
    prev: Link<T>,
    next: Link<T>,
}

impl<T> Node<T> {
    /// Allocate a new node on the heap and return a pointer to it.
    /// Ownership of the allocation is transferred to the caller, who must
    /// eventually free it with `Box::from_raw`.
    fn alloc(elem: T, prev: Link<T>, next: Link<T>) -> NonNull<Node<T>> {
        NonNull::from(Box::leak(Box::new(Node { elem, prev, next })))
    }
}

/// A doubly linked list.
///
/// Safety-critical invariants:
/// - Every node reachable from `head` (via `next`) or from `tail` (via `prev`)
///   was allocated by `Node::alloc` (i.e. a leaked `Box`) and is uniquely owned
///   by this list.
/// - `head` is `None` iff `tail` is `None` iff `len == 0`.
/// - For every node `n`: `n.next.prev == Some(n)` (if `n.next` exists) and
///   `n.prev.next == Some(n)` (if `n.prev` exists).
/// - `head.prev == None` and `tail.next == None`.
/// - `len` equals the number of nodes in the list.
pub struct LinkedList<T> {
    head: Link<T>,
    tail: Link<T>,
    len: usize,
    // Signals ownership of `T` values (for drop check). `NonNull` keeps us covariant.
    _marker: PhantomData<Box<Node<T>>>,
}

/// A cursor with mutable access to the list.
///
/// Invariant: `cur` is `None` iff the list is empty; otherwise it points to a
/// valid node belonging to `list`.
pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    cur: Link<T>,
}

/// An iterator over shared references to the list's elements.
///
/// Invariant: `next` is either `None` or points to a valid node of a list that
/// is immutably borrowed for `'a`.
pub struct Iter<'a, T> {
    next: Link<T>,
    _marker: PhantomData<&'a T>,
}

// SAFETY: The list uniquely owns its nodes, just like `Box<T>` / `Vec<T>`.
// Sending the list sends the `T`s it contains, so `T: Send` is required.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: A `&LinkedList<T>` only allows obtaining `&T` (via `iter`), so sharing
// it across threads is safe iff `T: Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: A cursor behaves like `&mut LinkedList<T>`, which is `Send` iff `T: Send`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
// SAFETY: A `&Cursor` gives no access to the elements (all methods take `&mut self`),
// but to be conservative we mirror `&mut LinkedList<T>`, which is `Sync` iff `T: Sync`.
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: `Iter` behaves like `&T`, which is `Send` and `Sync` iff `T: Sync`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let cur = self.head;
        Cursor { list: self, cur }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let cur = self.tail;
        Cursor { list: self, cur }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.head,
            _marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut link = self.head.take();
        self.tail = None;
        self.len = 0;
        while let Some(node) = link {
            // SAFETY: every node in the list was allocated via `Box` (Node::alloc)
            // and is uniquely owned by the list. We visit each node exactly once,
            // reading its `next` before freeing it, so no double free or
            // use-after-free occurs.
            let boxed = unsafe { Box::from_raw(node.as_ptr()) };
            link = boxed.next;
        }
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `cur` points to a valid node owned by the list (cursor invariant).
        // The cursor holds `&mut LinkedList`, so no other references to the
        // elements exist; the returned reference is tied to `&mut self`, so
        // no aliasing mutable references can be created through the cursor.
        self.cur.map(|node| unsafe { &mut (*node.as_ptr()).elem })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let cur = self.cur?;
        // SAFETY: `cur` points to a valid node of the list (cursor invariant).
        let next = unsafe { (*cur.as_ptr()).next };
        match next {
            Some(n) => {
                self.cur = Some(n);
                self.peek_mut()
            }
            None => None,
        }
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let cur = self.cur?;
        // SAFETY: `cur` points to a valid node of the list (cursor invariant).
        let prev = unsafe { (*cur.as_ptr()).prev };
        match prev {
            Some(p) => {
                self.cur = Some(p);
                self.peek_mut()
            }
            None => None,
        }
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let cur = self.cur?;
        // SAFETY: `cur` points to a valid node allocated via `Box` and owned by
        // the list (cursor + list invariants). We unlink it from all neighbours
        // and from head/tail below before anything else can observe it, so after
        // this the node is no longer reachable and we may take ownership back.
        let node = unsafe { Box::from_raw(cur.as_ptr()) };
        let Node { elem, prev, next } = *node;

        match prev {
            // SAFETY: `p` is a valid node of the list (link invariant), distinct
            // from the freed node.
            Some(p) => unsafe { (*p.as_ptr()).next = next },
            None => self.list.head = next,
        }
        match next {
            // SAFETY: `n` is a valid node of the list (link invariant), distinct
            // from the freed node.
            Some(n) => unsafe { (*n.as_ptr()).prev = prev },
            None => self.list.tail = prev,
        }
        self.list.len -= 1;
        self.cur = next.or(prev);
        Some(elem)
    }

    pub fn insert_after(&mut self, element: T) {
        match self.cur {
            None => self.insert_into_empty(element),
            Some(cur) => {
                // SAFETY: `cur` is a valid node of the list (cursor invariant).
                let next = unsafe { (*cur.as_ptr()).next };
                let new = Node::alloc(element, Some(cur), next);
                match next {
                    // SAFETY: `n` is a valid node of the list (link invariant).
                    Some(n) => unsafe { (*n.as_ptr()).prev = Some(new) },
                    None => self.list.tail = Some(new),
                }
                // SAFETY: `cur` is a valid node of the list (cursor invariant).
                unsafe { (*cur.as_ptr()).next = Some(new) };
                self.list.len += 1;
            }
        }
    }

    pub fn insert_before(&mut self, element: T) {
        match self.cur {
            None => self.insert_into_empty(element),
            Some(cur) => {
                // SAFETY: `cur` is a valid node of the list (cursor invariant).
                let prev = unsafe { (*cur.as_ptr()).prev };
                let new = Node::alloc(element, prev, Some(cur));
                match prev {
                    // SAFETY: `p` is a valid node of the list (link invariant).
                    Some(p) => unsafe { (*p.as_ptr()).next = Some(new) },
                    None => self.list.head = Some(new),
                }
                // SAFETY: `cur` is a valid node of the list (cursor invariant).
                unsafe { (*cur.as_ptr()).prev = Some(new) };
                self.list.len += 1;
            }
        }
    }

    /// Insert into an empty list. By the cursor invariant, `cur == None`
    /// implies the list is empty. The cursor is moved onto the new element.
    fn insert_into_empty(&mut self, element: T) {
        debug_assert!(self.list.is_empty());
        let new = Node::alloc(element, None, None);
        self.list.head = Some(new);
        self.list.tail = Some(new);
        self.list.len = 1;
        self.cur = Some(new);
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        self.next.map(|node| {
            // SAFETY: `node` points to a valid node of a list that is immutably
            // borrowed for `'a` (iterator invariant), so it cannot be mutated or
            // freed while the returned shared reference is alive.
            let node: &'a Node<T> = unsafe { &*node.as_ptr() };
            self.next = node.next;
            &node.elem
        })
    }
}
