The skeleton needs all five functions implemented. Each one is built only from `new Promise`, `.then` and `Promise.resolve`, so none of the built-in combinators are used.

- **`promisify`** returns a function that adds an error-first callback to the arguments. The promise rejects if an error is passed, and resolves with the data otherwise. It also forwards `this`, so promisified methods still work.
- **`all`** stores each resolved value at its original index and resolves once every promise has resolved. It rejects as soon as any promise rejects.
- **`allSettled`** stores either the resolved value or the rejection reason at each index. It resolves once everything has settled and never rejects.
- **`race`** settles the same way as the first promise to settle.
- **`any`** resolves with the first value to resolve. If every promise rejects, it rejects with an array of the reasons in input order.

Two edge cases are handled in every function:

- **No argument:** the returned promise resolves to `undefined`.
- **Empty array:** the returned promise resolves to `[]`.

Each input is passed through `Promise.resolve`, so plain values and thenables work too. Handlers are attached synchronously, so an already-rejected input never causes an unhandled rejection.

promises.js
```javascript
//
// Promise helpers re-implemented on top of the Promise constructor,
// without relying on the built-in combinators
// (Promise.all, Promise.allSettled, Promise.race, Promise.any).
//

/**
 * Turns a function following the "error-first callback" pattern into a
 * function returning a Promise.
 *
 * @param {Function} fn function whose last parameter is a callback `(error, data) => void`
 * @returns {Function} function taking the same arguments (without the callback) and returning a Promise
 */
export const promisify = (fn) => {
  if (typeof fn !== 'function') {
    throw new TypeError('The argument passed to promisify must be a function');
  }

  return function promisified(...args) {
    return new Promise((resolve, reject) => {
      fn.call(this, ...args, (error, data) => {
        if (error) {
          reject(error);
        } else {
          resolve(data);
        }
      });
    });
  };
};

/**
 * Resolves with an array of all resolved values (in input order) once every
 * promise has resolved, or rejects as soon as one of them rejects.
 *
 * - No argument: resolves with `undefined`.
 * - Empty array: resolves with `[]`.
 */
export const all = (promises) => {
  if (!promises) {
    return Promise.resolve();
  }

  return new Promise((resolve, reject) => {
    const items = [...promises];
    const values = new Array(items.length);
    let pending = items.length;

    if (pending === 0) {
      resolve(values);
      return;
    }

    items.forEach((item, index) => {
      Promise.resolve(item).then((value) => {
        values[index] = value;
        pending -= 1;
        if (pending === 0) {
          resolve(values);
        }
      }, reject);
    });
  });
};

/**
 * Resolves once every promise has settled (resolved or rejected), with an
 * array containing, in input order, either the resolved value or the
 * rejection reason of each promise. Never rejects.
 *
 * - No argument: resolves with `undefined`.
 * - Empty array: resolves with `[]`.
 */
export const allSettled = (promises) => {
  if (!promises) {
    return Promise.resolve();
  }

  return new Promise((resolve) => {
    const items = [...promises];
    const outcomes = new Array(items.length);
    let pending = items.length;

    if (pending === 0) {
      resolve(outcomes);
      return;
    }

    items.forEach((item, index) => {
      const settle = (outcome) => {
        outcomes[index] = outcome;
        pending -= 1;
        if (pending === 0) {
          resolve(outcomes);
        }
      };

      Promise.resolve(item).then(settle, settle);
    });
  });
};

/**
 * Settles exactly like the first promise to settle: resolves with its value
 * or rejects with its reason.
 *
 * - No argument: resolves with `undefined`.
 * - Empty array: resolves with `[]`.
 */
export const race = (promises) => {
  if (!promises) {
    return Promise.resolve();
  }

  return new Promise((resolve, reject) => {
    const items = [...promises];

    if (items.length === 0) {
      resolve([]);
      return;
    }

    items.forEach((item) => {
      Promise.resolve(item).then(resolve, reject);
    });
  });
};

/**
 * Resolves with the value of the first promise to resolve. If every promise
 * rejects, rejects with an array of all rejection reasons (in input order).
 *
 * - No argument: resolves with `undefined`.
 * - Empty array: resolves with `[]`.
 */
export const any = (promises) => {
  if (!promises) {
    return Promise.resolve();
  }

  return new Promise((resolve, reject) => {
    const items = [...promises];
    const errors = new Array(items.length);
    let pending = items.length;

    if (pending === 0) {
      resolve([]);
      return;
    }

    items.forEach((item, index) => {
      Promise.resolve(item).then(resolve, (error) => {
        errors[index] = error;
        pending -= 1;
        if (pending === 0) {
          reject(errors);
        }
      });
    });
  });
};
