const isPalindrome = (n) => {
  const s = String(n);
  let i = 0;
  let j = s.length - 1;
  while (i < j) {
    if (s[i] !== s[j]) return false;
    i++;
    j--;
  }
  return true;
};

const factorsOf = (value, min, max) => {
  if (value === null) return [];
  const result = [];
  for (let i = min; i <= max && i * i <= value; i++) {
    if (value % i === 0) {
      const j = value / i;
      if (j >= i && j <= max) {
        result.push([i, j]);
      }
    }
  }
  return result;
};

const findSmallest = (min, max) => {
  let best = null;
  for (let i = min; i <= max; i++) {
    if (best !== null && i * i > best) break;
    for (let j = i; j <= max; j++) {
      const p = i * j;
      if (best !== null && p >= best) break;
      if (isPalindrome(p)) {
        best = p;
        break;
      }
    }
  }
  return { value: best, factors: factorsOf(best, min, max) };
};

const findLargest = (min, max) => {
  let best = null;
  for (let i = max; i >= min; i--) {
    if (best !== null && i * max < best) break;
    for (let j = max; j >= i; j--) {
      const p = i * j;
      if (best !== null && p <= best) break;
      if (isPalindrome(p)) {
        best = p;
        break;
      }
    }
  }
  return { value: best, factors: factorsOf(best, min, max) };
};

export class Palindromes {
  static generate({ minFactor = 1, maxFactor } = {}) {
    if (minFactor > maxFactor) {
      throw new Error('min must be <= max');
    }

    let smallestCache;
    let largestCache;

    return {
      get smallest() {
        if (smallestCache === undefined) {
          smallestCache = findSmallest(minFactor, maxFactor);
        }
        return smallestCache;
      },
      get largest() {
        if (largestCache === undefined) {
          largestCache = findLargest(minFactor, maxFactor);
        }
        return largestCache;
      },
    };
  }
}
