```javascript
//
// Calculate how old someone would be on a planet in our Solar System,
// given their age in seconds.
//

const EARTH_YEAR_IN_SECONDS = 31557600;

const ORBITAL_PERIODS = {
  mercury: 0.2408467,
  venus: 0.61519726,
  earth: 1.0,
  mars: 1.8808158,
  jupiter: 11.862615,
  saturn: 29.447498,
  uranus: 84.016846,
  neptune: 164.79132,
};

const roundToTwoDecimals = (value) => Math.round(value * 100) / 100;

export const age = (planet, seconds) => {
  const key = typeof planet === 'string' ? planet.toLowerCase() : planet;

  if (!Object.prototype.hasOwnProperty.call(ORBITAL_PERIODS, key)) {
    throw new Error('not a planet');
  }

  const earthYears = seconds / EARTH_YEAR_IN_SECONDS;
  return roundToTwoDecimals(earthYears / ORBITAL_PERIODS[key]);
};
