    std::lock_guard<std::mutex> lock(mtx_);
    if (!open_) throw std::runtime_error("account not open");
    if (amount < 0) throw std::runtime_error("negative withdrawal");
    if (amount > balance_) throw std::runtime_error("insufficient funds");
    balance_ -= amount;
}

int Bankaccount::balance() {
    std::lock_guard<std::mutex> lock(mtx_);
    if (!open_) throw std::runtime_error("account not open");
    return balance_;
}

}  // namespace Bankaccount
