```
#include "bank_account.h"

#include <limits>

namespace Bankaccount {

namespace {

void require_positive(Bankaccount::amount_type amount) {
    if (amount <= 0) {
        throw std::runtime_error("amount must be greater than 0");
    }
}

}  // namespace

void Bankaccount::open() {
    std::lock_guard<std::mutex> lock(mutex_);
    if (open_) {
        throw std::runtime_error("account already open");
    }
    open_ = true;
    balance_ = 0;  // a (re)opened account never retains an old balance
}

void Bankaccount::close() {
    std::lock_guard<std::mutex> lock(mutex_);
    require_open();
    open_ = false;
}

void Bankaccount::deposit(amount_type amount) {
    std::lock_guard<std::mutex> lock(mutex_);
    require_open();
    require_positive(amount);
    // balance_ is never negative, so this subtraction cannot overflow.
    if (amount > std::numeric_limits<amount_type>::max() - balance_) {
        throw std::overflow_error("deposit would overflow the balance");
    }
    balance_ += amount;
}

void Bankaccount::withdraw(amount_type amount) {
    std::lock_guard<std::mutex> lock(mutex_);
    require_open();
    require_positive(amount);
