#include "queen_attack.h"

#include <cstdlib>

namespace queen_attack {

namespace {

constexpr int board_size = 8;

bool is_on_board(const chess_board::position& pos) {
    return pos.first >= 0 && pos.first < board_size &&
           pos.second >= 0 && pos.second < board_size;
}

}  // namespace

chess_board::chess_board()
    : chess_board(std::make_pair(0, 3), std::make_pair(7, 3)) {}

chess_board::chess_board(const position& white_pos, const position& black_pos)
    : white_{white_pos}, black_{black_pos} {
    if (!is_on_board(white_) || !is_on_board(black_)) {
        throw std::domain_error("queen must be placed on the board");
    }
    if (white_ == black_) {
        throw std::domain_error("queens cannot occupy the same position");
    }
}

chess_board::position chess_board::white() const { return white_; }

chess_board::position chess_board::black() const { return black_; }

bool chess_board::can_attack() const {
    const int row_diff = white_.first - black_.first;
    const int col_diff = white_.second - black_.second;
    return row_diff == 0 || col_diff == 0 ||
           std::abs(row_diff) == std::abs(col_diff);
}

chess_board::operator std::string() const {
    std::string board;
    for (int row = 0; row < board_size; ++row) {
        for (int col = 0; col < board_size; ++col) {
            if (col > 0) {
                board += ' ';
            }
            const position square{row, col};
            if (square == white_) {
                board += 'W';
            } else if (square == black_) {
                board += 'B';
            } else {
                board += '_';
            }
        }
        board += '\n';
    }
    return board;
}

}  // namespace queen_attack
