beer_song.go
```go
package beer

import (
	"errors"
	"fmt"
	"strings"
)

const (
	maxBottles = 99
	minBottles = 0
)

// Song returns the full lyrics of "99 Bottles of Beer on the Wall".
func Song() string {
	song, _ := Verses(maxBottles, minBottles)
	return song
}

// Verses returns the verses from start down to stop (inclusive),
// each followed by a blank line.
func Verses(start, stop int) (string, error) {
	if !validCount(start) || !validCount(stop) {
		return "", errors.New("verse numbers must be between 0 and 99")
	}
	if start < stop {
		return "", errors.New("start must be greater than or equal to stop")
	}

	var sb strings.Builder
	for n := start; n >= stop; n-- {
		v, err := Verse(n)
		if err != nil {
			return "", err
		}
		sb.WriteString(v)
		sb.WriteString("\n")
	}
	return sb.String(), nil
}

// Verse returns a single verse of the song for n bottles.
func Verse(n int) (string, error) {
	if !validCount(n) {
		return "", fmt.Errorf("invalid verse number: %d", n)
	}

	switch n {
	case 0:
		return "No more bottles of beer on the wall, no more bottles of beer.\n" +
			"Go to the store and buy some more, 99 bottles of beer on the wall.\n", nil
	case 1:
		return "1 bottle of beer on the wall, 1 bottle of beer.\n" +
			"Take it down and pass it around, no more bottles of beer on the wall.\n", nil
	case 2:
		return "2 bottles of beer on the wall, 2 bottles of beer.\n" +
			"Take one down and pass it around, 1 bottle of beer on the wall.\n", nil
	default:
		return fmt.Sprintf(
			"%d bottles of beer on the wall, %d bottles of beer.\n"+
				"Take one down and pass it around, %d bottles of beer on the wall.\n",
			n, n, n-1), nil
	}
}

func validCount(n int) bool {
	return n >= minBottles && n <= maxBottles
}
