	song, _ := Verses(maxBottles, 0)
	return song
}

// Verses returns the verses from start down to stop (inclusive),
// each verse followed by a blank line.
func Verses(start, stop int) (string, error) {
	switch {
	case !valid(start):
		return "", fmt.Errorf("start verse %d is out of range [0, %d]", start, maxBottles)
	case !valid(stop):
		return "", fmt.Errorf("stop verse %d is out of range [0, %d]", stop, maxBottles)
	case start < stop:
		return "", fmt.Errorf("start verse %d must not be less than stop verse %d", start, stop)
	}

	var b strings.Builder
	for n := start; n >= stop; n-- {
		b.WriteString(verse(n))
		b.WriteString("\n")
	}
	return b.String(), nil
}

// Verse returns the single verse sung when n bottles are on the wall.
func Verse(n int) (string, error) {
	if !valid(n) {
		return "", fmt.Errorf("verse %d is out of range [0, %d]", n, maxBottles)
	}
	return verse(n), nil
}

// verse builds the verse for n bottles; n is assumed to be valid.
func verse(n int) string {
	return fmt.Sprintf(
		"%s of beer on the wall, %s of beer.\n%s, %s of beer on the wall.\n",
		capitalize(bottles(n)), bottles(n), action(n), bottles(next(n)),
	)
}

func valid(n int) bool {
	return n >= 0 && n <= maxBottles
}

func bottles(n int) string {
	switch n {
	case 0:
		return "no more bottles"
	case 1:
		return "1 bottle"
	default:
		return fmt.Sprintf("%d bottles", n)
	}
}

func action(n int) string {
	switch n {
	case 0:
		return "Go to the store and buy some more"
	case 1:
		return "Take it down and pass it around"
	default:
		return "Take one down and pass it around"
	}
}

func next(n int) int {
	if n == 0 {
		return maxBottles
	}
	return n - 1
}

func capitalize(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}
