import (
	"errors"
	"math"
)

// ParseTrinary converts a trinary number represented as a string into its
// decimal int64 value. Invalid input or overflow results in 0 and an error.
func ParseTrinary(arg string) (int64, error) {
	if len(arg) == 0 {
		return 0, errors.New("empty input")
	}

	var result int64
	for _, r := range arg {
		var d int64
		switch r {
		case '0':
			d = 0
		case '1':
			d = 1
		case '2':
			d = 2
		default:
			return 0, errors.New("invalid trinary digit")
		}

		// Ensure result*3 + d does not overflow int64.
		if result > (math.MaxInt64-d)/3 {
			return 0, errors.New("value overflows int64")
		}
		result = result*3 + d
	}

	return result, nil
}
