`wordy.go` needs a full implementation. It reads the question left to right and ignores the usual order of operations, as the instructions require.

1. **Check the format.** The question must end with `?` and start with the words `What is`. I split it on whitespace rather than matching a fixed prefix, so `"What is?"` is handled correctly and rejected because it has no operand.
2. **Read the expression.** After `What is`, the words must follow the pattern `number (operator number)*`.
   - The operators are `plus`, `minus`, `multiplied by` and `divided by`.
   - For the two-word operators, the next word must be `by`.
3. **Return the result.** Each operation is applied as soon as it is read. If anything doesn't fit the pattern, the function returns `0, false`.
   - This covers unsupported operations like `cubed`, non-math questions, two operators or two numbers in a row, and prefix or postfix notation.
   - Dividing by zero also returns `0, false` instead of crashing.

wordy.go
```go
package wordy

import (
	"strconv"
	"strings"
)

// Answer parses and evaluates a simple math word problem such as
// "What is 5 plus 13 multiplied by 2?". Operations are evaluated strictly
// from left to right, ignoring the usual order of operations.
// It returns the result and true on success, or 0 and false if the
// question is not a valid, supported word problem.
func Answer(question string) (int, bool) {
	q := strings.TrimSpace(question)
	if !strings.HasSuffix(q, "?") {
		return 0, false
	}

	words := strings.Fields(strings.TrimSuffix(q, "?"))
	if len(words) < 3 || words[0] != "What" || words[1] != "is" {
		return 0, false
	}
	tokens := words[2:]

	result, ok := parseNumber(tokens[0])
	if !ok {
		return 0, false
	}

	for i := 1; i < len(tokens); {
		op := tokens[i]
		i++

		switch op {
		case "plus", "minus":
			// single-word operators, nothing more to consume
		case "multiplied", "divided":
			if i >= len(tokens) || tokens[i] != "by" {
				return 0, false
			}
			i++
		default:
			return 0, false
		}

		if i >= len(tokens) {
			return 0, false
		}
		operand, ok := parseNumber(tokens[i])
		if !ok {
			return 0, false
		}
		i++

		switch op {
		case "plus":
			result += operand
		case "minus":
			result -= operand
		case "multiplied":
			result *= operand
		case "divided":
			if operand == 0 {
				return 0, false
			}
			result /= operand
		}
	}

	return result, true
}

// parseNumber converts a token into an integer, reporting whether it succeeded.
func parseNumber(s string) (int, bool) {
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0, false
	}
	return n, true
}
