import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

class PythagoreanTriplet {

    private final int a;
    private final int b;
    private final int c;

    PythagoreanTriplet(int a, int b, int c) {
        this.a = a;
        this.b = b;
        this.c = c;
    }

    static TripletListBuilder makeTripletsList() {
        return new TripletListBuilder();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof PythagoreanTriplet)) {
            return false;
        }
        PythagoreanTriplet other = (PythagoreanTriplet) o;
        return a == other.a && b == other.b && c == other.c;
    }

    @Override
    public int hashCode() {
        return Objects.hash(a, b, c);
    }

    @Override
    public String toString() {
        return "PythagoreanTriplet{a=" + a + ", b=" + b + ", c=" + c + "}";
    }

    static class TripletListBuilder {

        private int sum;
        private int maxFactor = Integer.MAX_VALUE;

        TripletListBuilder thatSumTo(int sum) {
            this.sum = sum;
            return this;
        }

        TripletListBuilder withFactorsLessThanOrEqualTo(int maxFactor) {
            this.maxFactor = maxFactor;
            return this;
        }

        List<PythagoreanTriplet> build() {
            List<PythagoreanTriplet> triplets = new ArrayList<>();
            long n = sum;

            // From a + b + c = n and a^2 + b^2 = c^2 it follows that
            // b = n(n - 2a) / (2(n - a)), so only a needs to be iterated.
            for (long a = 1; 3 * a < n; a++) {
                long numerator = n * (n - 2 * a);
                long denominator = 2 * (n - a);

                // b decreases as a increases, so once b <= a no further solutions exist.
                if (numerator <= a * denominator) {
                    break;
                }
                if (numerator % denominator != 0) {
                    continue;
                }

                long b = numerator / denominator;
                long c = n - a - b;

                // Since a < b < c, all factors are within the limit iff c is.
                if (c <= maxFactor) {
                    triplets.add(new PythagoreanTriplet((int) a, (int) b, (int) c));
                }
            }

            return triplets;
        }

    }

}
```

