use std::fmt;

#[derive(Debug, PartialEq, Eq)]
pub enum Error {
    InvalidTonic(String),
    InvalidInterval(char),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::InvalidTonic(t) => write!(f, "invalid tonic: {t}"),
            Error::InvalidInterval(c) => write!(f, "invalid interval: {c}"),
        }
    }
}

impl std::error::Error for Error {}

const SHARPS: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];
const FLATS: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];
const FLAT_TONICS: [&str; 12] = [
    "F", "Bb", "Eb", "Ab", "Db", "Gb", "d", "g", "c", "f", "bb", "eb",
];

pub struct Scale {
    notes: Vec<String>,
}

fn normalize(tonic: &str) -> String {
    let mut chars = tonic.chars();
    match chars.next() {
        Some(first) => first.to_uppercase().chain(chars).collect(),
        None => String::new(),
    }
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let use_flats = FLAT_TONICS.contains(&tonic);
        let notes_list: &[&str; 12] = if use_flats { &FLATS } else { &SHARPS };
        let normalized = normalize(tonic);

        let start = notes_list
            .iter()
            .position(|n| *n == normalized)
            .or_else(|| {
                // Try the other list in case the tonic was spelled the other way.
                let other: &[&str; 12] = if use_flats { &SHARPS } else { &FLATS };
                other.iter().position(|n| *n == normalized)
            })
            .ok_or_else(|| Error::InvalidTonic(tonic.to_string()))?;

        let mut notes = vec![notes_list[start].to_string()];
        let mut idx = start;
        for c in intervals.chars() {
            let step = match c {
                'm' => 1,
                'M' => 2,
                'A' => 3,
                other => return Err(Error::InvalidInterval(other)),
            };
            idx = (idx + step) % 12;
            notes.push(notes_list[idx].to_string());
        }

        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, "mmmmmmmmmmmm")
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}
