//! Generate musical scales from a tonic and a pattern of intervals.

use std::fmt;

/// One way of writing the twelve pitches of the chromatic scale, from A up.
type Spelling = [&'static str; 12];

/// The chromatic scale written with sharps.
const SHARPS: Spelling = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];

/// The chromatic scale written with flats.
const FLATS: Spelling = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

/// Tonics whose scales are conventionally written with flats.
///
/// Upper-case tonics denote major keys and lower-case tonics minor keys, so
/// this lookup is deliberately case-sensitive: `"d"` (D minor) uses flats,
/// whereas `"D"` (D major) uses sharps.
const FLAT_TONICS: [&str; 12] = [
    "F", "Bb", "Eb", "Ab", "Db", "Gb", "d", "g", "c", "f", "bb", "eb",
];

/// The ways in which constructing a [`Scale`] can fail.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Error {
    /// The tonic is not a note of the chromatic scale.
    ///
    /// A tonic must be a letter from `A` to `G` (upper-case for major keys,
    /// lower-case for minor keys), optionally followed by `#` or `b`.
    InvalidTonic(String),
    /// The interval pattern contains a symbol other than `m` (half step),
    /// `M` (whole step) or `A` (augmented second).
    InvalidInterval(char),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::InvalidTonic(tonic) => write!(
                f,
                "invalid tonic {tonic:?}: expected a note such as \"C\", \"f#\" or \"Bb\""
            ),
            Error::InvalidInterval(interval) => write!(
                f,
                "invalid interval {interval:?}: expected 'm' (half step), \
                 'M' (whole step) or 'A' (augmented second)"
            ),
        }
    }
}

impl std::error::Error for Error {}

/// A musical scale: the tonic followed by the note reached after each
/// interval of the scale's pattern (so the usual scales end on the tonic
/// an octave higher).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Scale {
    notes: Vec<&'static str>,
}

impl Scale {
    /// Builds the scale starting at `tonic` and following `intervals`, where
    /// `m` is a half step, `M` a whole step and `A` an augmented second.
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let steps = intervals
            .chars()
            .map(semitones)
            .collect::<Result<Vec<_>, _>>()?;
        Scale::from_steps(tonic, steps)
    }

    /// Builds the chromatic scale, i.e. twelve consecutive half steps,
    /// starting at `tonic`.
    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::from_steps(tonic, [1; 12])
    }

    /// Lists the notes of the scale, starting with the tonic.
    pub fn enumerate(&self) -> Vec<String> {
        self.notes.iter().map(|&note| note.to_string()).collect()
    }

    /// Walks up from `tonic` by the given numbers of half steps, recording
    /// every note reached along the way.
    fn from_steps(tonic: &str, steps: impl IntoIterator<Item = usize>) -> Result<Scale, Error> {
        let (spelling, mut position) =
            locate(tonic).ok_or_else(|| Error::InvalidTonic(tonic.to_string()))?;

        let mut notes = vec![spelling[position]];
        for step in steps {
            position = (position + step) % spelling.len();
            notes.push(spelling[position]);
        }

        Ok(Scale { notes })
    }
}

/// The number of half steps spanned by an interval symbol.
fn semitones(interval: char) -> Result<usize, Error> {
    match interval {
        'm' => Ok(1),
        'M' => Ok(2),
        'A' => Ok(3),
        other => Err(Error::InvalidInterval(other)),
    }
}

/// Chooses how a scale starting at `tonic` should be spelled and finds the
/// tonic's position within that spelling.
///
/// Returns `None` if `tonic` isn't a note of the chromatic scale.
fn locate(tonic: &str) -> Option<(&'static Spelling, usize)> {
    let mut chars = tonic.chars();
    let letter = chars.next()?.to_ascii_uppercase();
    let accidental = chars.as_str();
    if !('A'..='G').contains(&letter) || !matches!(accidental, "" | "#" | "b") {
        return None;
    }

    // A flat tonic can only be written with flats, so this also covers keys
    // missing from the conventional list, such as "ab".
    let spelling: &'static Spelling = if accidental == "b" || FLAT_TONICS.contains(&tonic) {
        &FLATS
    } else {
        &SHARPS
    };

    let name = format!("{letter}{accidental}");
    let position = spelling.iter().position(|&note| note == name)?;
    Some((spelling, position))
}
```

