use std::fmt;

#[derive(Debug, PartialEq, Eq)]
pub enum Error {
    InvalidTonic(String),
    InvalidInterval(char),
    EmptyIntervals,
    IntervalsDoNotFormOctave(usize),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::InvalidTonic(t) => write!(f, "invalid tonic: {t}"),
            Error::InvalidInterval(c) => write!(f, "invalid interval: {c}"),
            Error::EmptyIntervals => write!(f, "no intervals given"),
            Error::IntervalsDoNotFormOctave(n) => {
                write!(f, "intervals sum to {n} half steps instead of 12")
            }
        }
    }
}

impl std::error::Error for Error {}

const SHARPS: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];
const FLATS: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];
const FLAT_TONICS: [&str; 12] = [
    "F", "Bb", "Eb", "Ab", "Db", "Gb", "d", "g", "c", "f", "bb", "eb",
];

pub struct Scale {
    notes: Vec<String>,
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        if intervals.is_empty() {
            return Err(Error::EmptyIntervals);
        }
        let steps = intervals
            .chars()
            .map(|c| match c {
                'm' => Ok(1),
                'M' => Ok(2),
                'A' => Ok(3),
                other => Err(Error::InvalidInterval(other)),
            })
            .collect::<Result<Vec<usize>, Error>>()?;
        let total: usize = steps.iter().sum();
        if total != 12 {
            return Err(Error::IntervalsDoNotFormOctave(total));
        }

        let names = if FLAT_TONICS.contains(&tonic) {
            &FLATS
        } else {
            &SHARPS
        };

        let normalized = normalize(tonic);
        let start = SHARPS
            .iter()
            .position(|n| *n == normalized)
            .or_else(|| FLATS.iter().position(|n| *n == normalized))
            .ok_or_else(|| Error::InvalidTonic(tonic.to_string()))?;

        let mut notes = Vec::with_capacity(steps.len() + 1);
        let mut idx = start;
        notes.push(names[idx].to_string());
        for step in steps {
            idx = (idx + step) % 12;
            notes.push(names[idx].to_string());
        }
        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, "mmmmmmmmmmmm")
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}

fn normalize(tonic: &str) -> String {
    let mut chars = tonic.chars();
    match chars.next() {
        Some(first) => {
            let mut s = first.to_ascii_uppercase().to_string();
            s.extend(chars);
            s
        }
        None => String::new(),
    }
}
```

