use std::fmt;

/// Errors which may occur while constructing a scale.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Error {
    /// The tonic could not be parsed as a valid note.
    InvalidTonic(String),
    /// The interval string contained an unknown interval character.
    InvalidInterval(char),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::InvalidTonic(t) => write!(f, "invalid tonic: {t:?}"),
            Error::InvalidInterval(c) => write!(f, "invalid interval: {c:?}"),
        }
    }
}

impl std::error::Error for Error {}

const SHARPS: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];

const FLATS: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

pub struct Scale {
    /// Index of the tonic within the chromatic scale (A = 0).
    tonic: usize,
    /// Whether to spell notes using flats (otherwise sharps).
    use_flats: bool,
    /// Steps (in semitones) between consecutive notes.
    steps: Vec<usize>,
}

fn parse_tonic(tonic: &str) -> Result<usize, Error> {
    let invalid = || Error::InvalidTonic(tonic.to_string());

    let mut chars = tonic.chars();
    let letter = chars.next().ok_or_else(invalid)?;
    let base: i32 = match letter.to_ascii_uppercase() {
        'A' => 0,
        'B' => 2,
        'C' => 3,
        'D' => 5,
        'E' => 7,
        'F' => 8,
        'G' => 10,
        _ => return Err(invalid()),
    };

    let offset: i32 = match chars.as_str() {
        "" => 0,
        "#" => 1,
        "b" => -1,
        _ => return Err(invalid()),
    };

    Ok((base + offset).rem_euclid(12) as usize)
}

fn uses_flats(tonic: &str) -> bool {
    match tonic {
        // Natural tonics which use flats: F major; d, g, c, f minor.
        "F" | "d" | "g" | "c" | "f" => true,
        // Any flat tonic (Bb, Eb, Ab, Db, Gb, bb, eb, ...) uses flats.
        _ => tonic.len() == 2 && tonic.ends_with('b'),
    }
}

fn parse_intervals(intervals: &str) -> Result<Vec<usize>, Error> {
    intervals
        .chars()
        .map(|c| match c {
            'm' => Ok(1),
            'M' => Ok(2),
            'A' => Ok(3),
            other => Err(Error::InvalidInterval(other)),
        })
        .collect()
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let tonic_index = parse_tonic(tonic)?;
        let steps = parse_intervals(intervals)?;
        Ok(Scale {
            tonic: tonic_index,
            use_flats: uses_flats(tonic),
            steps,
        })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, &"m".repeat(12))
    }

    pub fn enumerate(&self) -> Vec<String> {
        let names: &[&str; 12] = if self.use_flats { &FLATS } else { &SHARPS };

        let mut out = Vec::with_capacity(self.steps.len() + 1);
        let mut index = self.tonic;
        out.push(names[index].to_string());
        for &step in &self.steps {
            index = (index + step) % 12;
            out.push(names[index].to_string());
        }
        out
    }
}
```

