pub mod graph {
    use std::collections::HashMap;

    use self::graph_items::edge::Edge;
    use self::graph_items::node::Node;

    /// Copies borrowed `(key, value)` pairs into an owned attribute map.
    /// A later pair overrides an earlier one that has the same key.
    fn extend_attrs(map: &mut HashMap<String, String>, attrs: &[(&str, &str)]) {
        map.extend(
            attrs
                .iter()
                .map(|&(key, value)| (key.to_string(), value.to_string())),
        );
    }

    pub mod graph_items {
        pub mod edge {
            use std::collections::HashMap;

            /// A connection between two nodes (referenced by name),
            /// optionally carrying attributes such as `color`.
            #[derive(Clone, Debug, PartialEq, Eq)]
            pub struct Edge {
                from: String,
                to: String,
                attrs: HashMap<String, String>,
            }

            impl Edge {
                /// Creates an edge between the nodes named `from` and `to`, without attributes.
                pub fn new(from: &str, to: &str) -> Self {
                    Self {
                        from: from.to_string(),
                        to: to.to_string(),
                        attrs: HashMap::new(),
                    }
                }

                /// Builder method: adds (or overrides) attributes on this edge.
                pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
                    crate::graph::extend_attrs(&mut self.attrs, attrs);
                    self
                }

                /// The names of the two nodes this edge connects.
                pub fn endpoints(&self) -> (&str, &str) {
                    (self.from.as_str(), self.to.as_str())
                }

                /// Looks up the value of the attribute `key`, if present.
                pub fn attr(&self, key: &str) -> Option<&str> {
                    self.attrs.get(key).map(String::as_str)
                }

                /// Alias of [`Edge::attr`], kept for compatibility.
                pub fn get_attr(&self, key: &str) -> Option<&str> {
                    self.attr(key)
                }
            }
        }

        pub mod node {
            use std::collections::HashMap;

            /// A named vertex of the graph, optionally carrying attributes such as `color`.
            #[derive(Clone, Debug, PartialEq, Eq)]
            pub struct Node {
                name: String,
                attrs: HashMap<String, String>,
            }

            impl Node {
                /// Creates a node called `name`, without attributes.
                pub fn new(name: &str) -> Self {
                    Self {
                        name: name.to_string(),
                        attrs: HashMap::new(),
                    }
                }

                /// Builder method: adds (or overrides) attributes on this node.
                pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
                    crate::graph::extend_attrs(&mut self.attrs, attrs);
                    self
                }

                /// The node's name.
                pub fn name(&self) -> &str {
                    &self.name
                }

                /// Looks up the value of the attribute `key`, if present.
                pub fn attr(&self, key: &str) -> Option<&str> {
                    self.attrs.get(key).map(String::as_str)
                }

                /// Alias of [`Node::attr`], kept for compatibility.
                pub fn get_attr(&self, key: &str) -> Option<&str> {
                    self.attr(key)
                }
            }
        }
    }

    /// A graph description: its nodes, its edges and graph-level attributes.
    #[derive(Clone, Debug, Default, PartialEq, Eq)]
    pub struct Graph {
        pub nodes: Vec<Node>,
        pub edges: Vec<Edge>,
        pub attrs: HashMap<String, String>,
    }

    impl Graph {
        /// Creates an empty graph: no nodes, no edges, no attributes.
        pub fn new() -> Self {
            Self::default()
        }

        /// Builder method: appends (copies of) `nodes` to the graph.
        pub fn with_nodes(mut self, nodes: &[Node]) -> Self {
            self.nodes.extend_from_slice(nodes);
            self
        }

        /// Builder method: appends (copies of) `edges` to the graph.
        pub fn with_edges(mut self, edges: &[Edge]) -> Self {
            self.edges.extend_from_slice(edges);
            self
        }

        /// Builder method: adds (or overrides) graph-level attributes.
        pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
            extend_attrs(&mut self.attrs, attrs);
            self
        }

        /// Finds the node called `name`, if the graph contains one.
        pub fn node(&self, name: &str) -> Option<&Node> {
            self.nodes.iter().find(|node| node.name() == name)
        }

        /// Alias of [`Graph::node`], kept for compatibility.
        pub fn get_node(&self, name: &str) -> Option<&Node> {
            self.node(name)
        }

        /// Looks up the value of the graph-level attribute `key`, if present.
        pub fn attr(&self, key: &str) -> Option<&str> {
            self.attrs.get(key).map(String::as_str)
        }
    }
}
