```
//! Generate musical scales from a tonic and a pattern of intervals.

use std::fmt;

/// Errors which can occur while constructing a [`Scale`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Error {
    /// The tonic is not a valid note name such as `C`, `f#` or `Bb`.
    InvalidTonic(String),
    /// The interval pattern contains a symbol other than `m`, `M` or `A`.
    InvalidInterval(char),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::InvalidTonic(tonic) => write!(
                f,
                "invalid tonic {tonic:?}: expected a letter A-G optionally followed by '#' or 'b'"
            ),
            Error::InvalidInterval(symbol) => write!(
                f,
                "invalid interval {symbol:?}: expected 'm' (half step), 'M' (whole step) or 'A' (augmented second)"
            ),
        }
    }
}

impl std::error::Error for Error {}

/// Number of distinct pitches in the chromatic scale.
const SEMITONES: u8 = 12;

/// The chromatic scale beginning at A, written with sharps.
const SHARP_NAMES: [&str; SEMITONES as usize] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];

/// The chromatic scale beginning at A, written with flats.
const FLAT_NAMES: [&str; SEMITONES as usize] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

/// Whether the notes of a scale are written using sharps or flats.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Spelling {
    Sharps,
    Flats,
}

impl Spelling {
    /// The spelling used by a key whose tonic is a natural note.
    ///
    /// Uppercase letters denote major keys and lowercase letters minor keys:
    ///
    /// | Key signature | Major                 | Minor                |
    /// | ------------- | --------------------- | -------------------- |
    /// | Natural       | C                     | a                    |
    /// | Sharps        | G, D, A, E, B, F#     | e, b, f#, c#, g#, d# |
    /// | Flats         | F, Bb, Eb, Ab, Db, Gb | d, g, c, f, bb, eb   |
    ///
    /// Of the natural tonics only F major and d, g, c and f minor are written
    /// with flats. C major and a minor have no accidentals and conventionally
    /// ascend using sharps, like the remaining natural keys.
    fn of_natural_key(letter: char) -> Self {
        if matches!(letter, 'F' | 'd' | 'g' | 'c' | 'f') {
            Spelling::Flats
        } else {
            Spelling::Sharps
        }
    }

    /// The name of a pitch class (counted in half steps above A).
    fn name(self, pitch: u8) -> &'static str {
        let names = match self {
            Spelling::Sharps => &SHARP_NAMES,
            Spelling::Flats => &FLAT_NAMES,
        };
        names[usize::from(pitch % SEMITONES)]
    }
}

/// The interval between two consecutive notes of a scale.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Interval {
    /// A half step, written `m`.
    MinorSecond,
    /// A whole step, written `M`.
    MajorSecond,
    /// A whole step plus a half step, written `A`.
    AugmentedSecond,
}

impl Interval {
    fn from_symbol(symbol: char) -> Result<Self, Error> {
        match symbol {
            'm' => Ok(Interval::MinorSecond),
            'M' => Ok(Interval::MajorSecond),
            'A' => Ok(Interval::AugmentedSecond),
            other => Err(Error::InvalidInterval(other)),
        }
    }

    fn semitones(self) -> u8 {
        match self {
            Interval::MinorSecond => 1,
            Interval::MajorSecond => 2,
            Interval::AugmentedSecond => 3,
        }
    }
}

/// The starting note of a scale.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Tonic {
    /// Pitch class, counted in half steps above A.
    pitch: u8,
    /// How the notes of a scale built on this tonic are written.
    spelling: Spelling,
}

impl Tonic {
    /// Parses a tonic such as `C`, `f#` or `Bb`.
    ///
    /// A sharp tonic produces a scale written with sharps and a flat tonic
    /// one written with flats; natural tonics follow the key signature table.
    fn parse(tonic: &str) -> Result<Self, Error> {
        let invalid = || Error::InvalidTonic(tonic.to_string());

        let mut chars = tonic.chars();
        let letter = chars.next().ok_or_else(invalid)?;
        let natural: u8 = match letter.to_ascii_uppercase() {
            'A' => 0,
            'B' => 2,
            'C' => 3,
            'D' => 5,
            'E' => 7,
            'F' => 8,
            'G' => 10,
            _ => return Err(invalid()),
        };

        let (pitch, spelling) = match chars.next() {
            None => (natural, Spelling::of_natural_key(letter)),
            Some('#') | Some('♯') => ((natural + 1) % SEMITONES, Spelling::Sharps),
            Some('b') | Some('♭') => ((natural + SEMITONES - 1) % SEMITONES, Spelling::Flats),
            Some(_) => return Err(invalid()),
        };

        if chars.next().is_some() {
            return Err(invalid());
        }

        Ok(Tonic { pitch, spelling })
    }
}

/// A musical scale: a tonic together with the intervals between its notes.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Scale {
    tonic: Tonic,
    intervals: Vec<Interval>,
}

impl Scale {
    /// Creates the scale which starts on `tonic` and follows the given
    /// pattern of `intervals`: `m` is a half step, `M` a whole step and `A`
    /// an augmented second (a whole step plus a half step).
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        Ok(Scale {
            tonic: Tonic::parse(tonic)?,
            intervals: intervals
                .chars()
                .map(Interval::from_symbol)
                .collect::<Result<Vec<_>, _>>()?,
        })
    }

    /// Creates the chromatic scale starting on `tonic`: twelve half steps
    /// spanning a full octave.
    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Ok(Scale {
            tonic: Tonic::parse(tonic)?,
            intervals: vec![Interval::MinorSecond; usize::from(SEMITONES)],
        })
    }

    /// Lists the notes of the scale: the tonic followed by one note for each
    /// interval. A pattern spanning a full octave therefore ends on the tonic.
    pub fn enumerate(&self) -> Vec<String> {
        let spelling = self.tonic.spelling;
        let mut pitch = self.tonic.pitch;

        let mut notes = Vec::with_capacity(self.intervals.len() + 1);
        notes.push(spelling.name(pitch).to_string());
        for interval in &self.intervals {
            pitch = (pitch + interval.semitones()) % SEMITONES;
            notes.push(spelling.name(pitch).to_string());
        }
        notes
    }
}
