use std::fmt;

/// Errors that can occur while constructing a scale.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Error {
    /// The tonic could not be parsed as a valid note.
    InvalidTonic(String),
    /// An interval character was not one of `m`, `M`, or `A`.
    InvalidInterval(char),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::InvalidTonic(t) => write!(f, "invalid tonic: {t:?}"),
            Error::InvalidInterval(c) => write!(f, "invalid interval: {c:?}"),
        }
    }
}

impl std::error::Error for Error {}

const SHARPS: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];

const FLATS: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

/// Tonics (case-sensitive: uppercase = major, lowercase = minor) whose
/// scales are written using flats.
const FLAT_TONICS: [&str; 12] = [
    "F", "Bb", "Eb", "Ab", "Db", "Gb", "d", "g", "c", "f", "bb", "eb",
];

pub struct Scale {
    tonic: usize,
    use_flats: bool,
    steps: Vec<usize>,
}

fn parse_tonic(tonic: &str) -> Result<usize, Error> {
    let err = || Error::InvalidTonic(tonic.to_string());
    let mut chars = tonic.chars();

    let letter = chars.next().ok_or_else(err)?;
    let base: i32 = match letter.to_ascii_uppercase() {
        'A' => 0,
        'B' => 2,
        'C' => 3,
        'D' => 5,
        'E' => 7,
        'F' => 8,
        'G' => 10,
        _ => return Err(err()),
    };

    let offset: i32 = match chars.next() {
        None => 0,
        Some('#') => 1,
        Some('b') => -1,
        Some(_) => return Err(err()),
    };

    if chars.next().is_some() {
        return Err(err());
    }

    Ok((base + offset).rem_euclid(12) as usize)
}

fn parse_intervals(intervals: &str) -> Result<Vec<usize>, Error> {
    intervals
        .chars()
        .map(|c| match c {
            'm' => Ok(1),
            'M' => Ok(2),
            'A' => Ok(3),
            other => Err(Error::InvalidInterval(other)),
        })
        .collect()
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let index = parse_tonic(tonic)?;
        let steps = parse_intervals(intervals)?;
        let use_flats = FLAT_TONICS.contains(&tonic);
        Ok(Scale {
            tonic: index,
            use_flats,
            steps,
        })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, "mmmmmmmmmmmm")
    }

    pub fn enumerate(&self) -> Vec<String> {
        let names: &[&str; 12] = if self.use_flats { &FLATS } else { &SHARPS };
        let mut idx = self.tonic;
        let mut out = Vec::with_capacity(self.steps.len() + 1);
        out.push(names[idx].to_string());
        for &step in &self.steps {
            idx = (idx + step) % 12;
            out.push(names[idx].to_string());
        }
        out
    }
}
```

