```rust
#[derive(Debug)]
pub enum Error {
    InvalidTonic(String),
    InvalidInterval(char),
}

const SHARPS: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];
const FLATS: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

const FLAT_TONICS: [&str; 12] = [
    "F", "Bb", "Eb", "Ab", "Db", "Gb", "d", "g", "c", "f", "bb", "eb",
];

pub struct Scale {
    notes: Vec<String>,
}

fn normalize(tonic: &str) -> String {
    let mut chars = tonic.chars();
    match chars.next() {
        Some(first) => {
            let mut s = first.to_ascii_uppercase().to_string();
            s.push_str(&chars.as_str().to_ascii_lowercase());
            s
        }
        None => String::new(),
    }
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let table: &[&str; 12] = if FLAT_TONICS.contains(&tonic) {
            &FLATS
        } else {
            &SHARPS
        };
        let name = normalize(tonic);
        let start = table
            .iter()
            .position(|&n| n == name)
            .or_else(|| {
                // Allow tonics spelled in the other notation
                let other: &[&str; 12] = if std::ptr::eq(table, &FLATS) {
                    &SHARPS
                } else {
                    &FLATS
                };
                other.iter().position(|&n| n == name)
            })
            .ok_or_else(|| Error::InvalidTonic(tonic.to_string()))?;

        let mut notes = vec![table[start].to_string()];
        let mut idx = start;
        for c in intervals.chars() {
            let step = match c {
                'm' => 1,
                'M' => 2,
                'A' => 3,
                other => return Err(Error::InvalidInterval(other)),
            };
            idx = (idx + step) % 12;
            notes.push(table[idx].to_string());
        }
        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, "mmmmmmmmmmmm")
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}
