#include "perfect_numbers.h"

#include <stdexcept>

namespace perfect_numbers {

namespace {

// Sum of all divisors of n excluding n itself.
long long aliquot_sum(long long n) {
    if (n == 1) {
        return 0;
    }

    long long sum = 1;  // 1 is a proper divisor of every n > 1
    for (long long i = 2; i * i <= n; ++i) {
        if (n % i == 0) {
            sum += i;
            const long long paired = n / i;
            if (paired != i) {
                sum += paired;
            }
        }
    }
    return sum;
}

}  // namespace

classification classify(int n) {
    if (n <= 0) {
        throw std::domain_error(
            "Classification is only possible for positive integers.");
    }

    const long long value = n;
    const long long sum = aliquot_sum(value);

    if (sum == value) {
        return classification::perfect;
    }
    if (sum > value) {
        return classification::abundant;
    }
    return classification::deficient;
}

}  // namespace perfect_numbers
