The test suite calls `Palindromes.generate({ minFactor, maxFactor })` and reads `.smallest` and `.largest`. Each one is an object `{ value, factors }`.

**How it works:**
- **Input check:** `generate` throws `min must be <= max` if the range is invalid.
- **Lazy results:** `smallest` and `largest` are getters. Each is computed only when first accessed, then cached.
- **Fast search:** each search stops early as soon as no remaining product can beat the best palindrome found so far. This keeps large ranges (4–5 digit factors) fast.
- **Factor pairs:** once the palindrome is found, every pair `[a, b]` with `min <= a <= b <= max` and `a * b = value` is collected.
- **No palindrome:** the result is `{ value: null, factors: [] }`.

palindrome-products.js
```javascript
//
// Palindrome Products
//

const isPalindrome = (n) => {
  if (n < 0) return false;
  if (n < 10) return true;
  if (n % 10 === 0) return false;
  let original = n;
  let reversed = 0;
  while (n > 0) {
    reversed = reversed * 10 + (n % 10);
    n = Math.floor(n / 10);
  }
  return reversed === original;
};

export class Palindromes {
  constructor(minFactor, maxFactor) {
    this.minFactor = minFactor;
    this.maxFactor = maxFactor;
    this._smallest = undefined;
    this._largest = undefined;
  }

  static generate({ minFactor = 1, maxFactor } = {}) {
    if (minFactor > maxFactor) {
      throw new Error('min must be <= max');
    }
    return new Palindromes(minFactor, maxFactor);
  }

  get smallest() {
    if (this._smallest === undefined) {
      this._smallest = this._buildResult(this._findSmallest());
    }
    return this._smallest;
  }

  get largest() {
    if (this._largest === undefined) {
      this._largest = this._buildResult(this._findLargest());
    }
    return this._largest;
  }

  _findSmallest() {
    const min = this.minFactor;
    const max = this.maxFactor;
    let best = Infinity;

    for (let i = min; i <= max; i++) {
      if (i * i > best) break;
      for (let j = i; j <= max; j++) {
        const product = i * j;
        if (product >= best) break;
        if (isPalindrome(product)) {
          best = product;
          break;
        }
      }
    }

    return best === Infinity ? null : best;
  }

  _findLargest() {
    const min = this.minFactor;
