**How it works:**

- **API:** `Palindromes.generate({ minFactor, maxFactor })` returns an object with `smallest` and `largest` getters. Each getter returns `{ value, factors }`. Each result is computed only when first read, then cached.
- **Validation:** if `minFactor > maxFactor`, it throws `Error('min must be <= max')`. `minFactor` defaults to `1` if it is not given.
- **Search with pruning:** only pairs with `a ≤ b` are checked.
  - **Smallest:** rows go upward from `min`. A row stops at its first palindrome, or once products reach the best value found so far. The whole search stops once `a * a` reaches that best value.
  - **Largest:** rows go downward from `max`. A row stops at its first palindrome, or once products fall to the best value found so far. The whole search stops once `a * max` falls to that best value.
  - This keeps even the 4-digit ranges fast.
- **Factor pairs:** once the palindrome value is known, every pair `[a, b]` is collected where `min ≤ a ≤ b ≤ max` and `a * b === value`. Only candidates `a` from `max(min, ceil(value / max))` up to `√value` are checked.
- **No palindrome found:** the result is `{ value: null, factors: [] }`.

palindrome-products.js
```javascript
//
// Palindrome Products
//
// Finds the smallest and largest palindromic numbers that are products of
// two factors within a given (inclusive) range, together with every pair of
// factors within that range that produces them.
//

/**
 * Checks whether a non-negative integer reads the same forwards and backwards.
 *
 * @param {number} n
 * @returns {boolean}
 */
const isPalindrome = (n) => {
  if (n < 0) return false;
  // A non-zero number ending in 0 would need a leading 0 to be a palindrome.
  if (n !== 0 && n % 10 === 0) return false;

  let reversed = 0;
  let rest = n;
  while (rest > 0) {
    reversed = reversed * 10 + (rest % 10);
    rest = Math.floor(rest / 10);
  }
  return reversed === n;
};

/**
 * Finds the smallest palindromic product a * b with min <= a <= b <= max.
 *
 * @param {number} min
 * @param {number} max
 * @returns {number|null}
 */
const findSmallest = (min, max) => {
  let best = null;

  for (let a = min; a <= max; a++) {
    // a * a is the smallest product in this row (and in every later row).
    if (best !== null && a * a >= best) break;

    for (let b = a; b <= max; b++) {
      const product = a * b;
      // Products only grow along the row, so nothing better remains here.
      if (best !== null && product >= best) break;
      if (isPalindrome(product)) {
        best = product;
        break;
      }
    }
  }

  return best;
};

/**
 * Finds the largest palindromic product a * b with min <= a <= b <= max.
 *
 * @param {number} min
 * @param {number} max
 * @returns {number|null}
 */
const findLargest = (min, max) => {
  let best = null;

  for (let a = max; a >= min; a--) {
    // a * max is the largest product in this row (and in every later row).
    if (best !== null && a * max <= best) break;

    for (let b = max; b >= a; b--) {
      const product = a * b;
      // Products only shrink along the row, so nothing better remains here.
      if (best !== null && product <= best) break;
      if (isPalindrome(product)) {
        best = product;
        break;
      }
    }
  }

  return best;
};

/**
 * Collects every pair [a, b] with min <= a <= b <= max and a * b === value.
 *
 * @param {number|null} value
 * @param {number} min
 * @param {number} max
 * @returns {Array<[number, number]>}
 */
const factorPairs = (value, min, max) => {
  const pairs = [];
  if (value === null) return pairs;

  if (value === 0) {
    // Only reachable when 0 is within the range: 0 pairs with every factor.
    for (let b = 0; b <= max; b++) pairs.push([0, b]);
    return pairs;
  }

  // b = value / a <= max  <=>  a >= value / max
  // a <= b                <=>  a * a <= value
  for (let a = Math.max(min, Math.ceil(value / max)); a * a <= value; a++) {
    if (value % a === 0) pairs.push([a, value / a]);
  }

  return pairs;
};

export class Palindromes {
  constructor(minFactor, maxFactor) {
    this.minFactor = minFactor;
    this.maxFactor = maxFactor;
    this.cachedSmallest = undefined;
    this.cachedLargest = undefined;
  }

  static generate({ minFactor = 1, maxFactor } = {}) {
    if (minFactor > maxFactor) {
      throw new Error('min must be <= max');
    }
    return new Palindromes(minFactor, maxFactor);
  }

  get smallest() {
    if (this.cachedSmallest === undefined) {
      this.cachedSmallest = this.buildResult(
        findSmallest(this.minFactor, this.maxFactor),
      );
    }
    return this.cachedSmallest;
  }

  get largest() {
    if (this.cachedLargest === undefined) {
      this.cachedLargest = this.buildResult(
        findLargest(this.minFactor, this.maxFactor),
      );
    }
    return this.cachedLargest;
  }

  buildResult(value) {
    return {
      value,
      factors: factorPairs(value, this.minFactor, this.maxFactor),
    };
  }
}
