class EmptyListException(Exception):
    """Exception raised when an operation requires a non-empty linked list.

    message: explanation of the error.
    """

    def __init__(self, message="The list is empty."):
        super().__init__(message)
        self.message = message


class Node:
    """A single element (song) of a singly linked list."""

    def __init__(self, value, next_node=None):
        self._value = value
        self._next = next_node

    def value(self):
        return self._value

    def next(self):
        return self._next


class LinkedList:
    """A LIFO stack implemented as a custom singly linked list."""

    def __init__(self, values=None):
        self._head = None
        self._length = 0
        if values is not None:
            for value in values:
                self.push(value)

    def __iter__(self):
        current = self._head
        while current is not None:
            yield current.value()
            current = current.next()

    def __len__(self):
        return self._length

    def head(self):
        if self._head is None:
            raise EmptyListException("The list is empty.")
        return self._head

    def push(self, value):
        self._head = Node(value, self._head)
        self._length += 1

    def pop(self):
        if self._head is None:
            raise EmptyListException("The list is empty.")
        node = self._head
        self._head = node.next()
        self._length -= 1
        return node.value()

    def reversed(self):
        # Pushing values in head-to-tail order onto a new list
        # leaves them in the opposite order.
        return LinkedList(self)
