#if !defined(BANK_ACCOUNT_H)
#define BANK_ACCOUNT_H

#include <mutex>
#include <stdexcept>

namespace Bankaccount {
// A bank account that can safely be used from multiple threads at once.
// Every operation acquires the account's mutex, so reading the balance and
// storing the new balance happen atomically with respect to other operations.
//
// All failures (operating on an account that is not open, invalid amounts,
// insufficient funds, ...) are reported by throwing std::runtime_error
// (or a type derived from it).
class Bankaccount {
   public:
    Bankaccount() = default;

    // The account owns a mutex, so it can be neither copied nor moved.
    Bankaccount(const Bankaccount&) = delete;
    Bankaccount& operator=(const Bankaccount&) = delete;

    void open();
    void close();

    void deposit(int amount);
    void withdraw(int amount);
    int balance() const;

   private:
    // Throws if the account is not open. Caller must hold mutex_.
    void ensure_open() const;

    mutable std::mutex mutex_;
    bool is_open_{false};
    int balance_{0};
};  // class Bankaccount

}  // namespace Bankaccount

#endif  // BANK_ACCOUNT_H
