The stub needs a builder-style API: `Graph`, `Node` and `Edge`, each with chainable `with_*` methods.

**Module layout.** The types live at `graph::Graph`, `graph::graph_items::node::Node` and `graph::graph_items::edge::Edge`.

**`Graph`**
- Has public fields `nodes: Vec<Node>`, `edges: Vec<Edge>` and `attrs: HashMap<String, String>`.
- The builder methods `with_nodes`, `with_edges` and `with_attrs` each take ownership of `self` and return it, so calls can be chained.
- `node(name)` finds a node by name, and `attr(key)` looks up a graph attribute.

**`Node`**
- `Node::new(name)` creates a node with no attributes.
- `with_attrs(&[(k, v)])` adds attributes and returns the node, so it can be chained.
- `attr(key)` returns `Option<&str>`, and `name()` returns the node's name.

**`Edge`**
- `Edge::new(from, to)` creates an edge with no attributes.
- It has the same `with_attrs` and `attr` methods as `Node`, plus `from()` and `to()` accessors.

**Shared details**
- All attribute handling goes through one private helper. When a key is repeated, the last value wins.
- The types derive `Debug`, `Clone`, `PartialEq` and `Eq`, so they can be compared, printed and copied out of slices.
- `Graph` also derives `Default`, and `Graph::new()` uses it.

src/lib.rs
```
//! An internal DSL, inspired by the Graphviz DOT language, for describing
//! graphs using the builder pattern.

pub mod graph {
    use std::collections::HashMap;

    use self::graph_items::edge::Edge;
    use self::graph_items::node::Node;

    /// Copies borrowed `(key, value)` pairs into an owned attribute map.
    ///
    /// When the same key appears more than once, the last value wins.
    fn extend_attrs(target: &mut HashMap<String, String>, attrs: &[(&str, &str)]) {
        target.extend(
            attrs
                .iter()
                .map(|&(key, value)| (key.to_string(), value.to_string())),
        );
    }

    pub mod graph_items {
        pub mod node {
            use std::collections::HashMap;

            use crate::graph::extend_attrs;

            /// A named vertex of a graph, e.g. `a [color="red"]`.
            #[derive(Debug, Clone, PartialEq, Eq)]
            pub struct Node {
                name: String,
                attrs: HashMap<String, String>,
            }

            impl Node {
                /// Creates a node with the given name and no attributes.
                pub fn new(name: &str) -> Self {
                    Self {
                        name: name.to_string(),
                        attrs: HashMap::new(),
                    }
                }

                /// Adds attributes to the node, overwriting existing values
                /// stored under the same keys.
                #[must_use]
                pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
                    extend_attrs(&mut self.attrs, attrs);
                    self
                }

                /// Returns the node's name.
                pub fn name(&self) -> &str {
                    &self.name
                }

                /// Returns the value of the attribute `key`, if it is set.
                pub fn attr(&self, key: &str) -> Option<&str> {
                    self.attrs.get(key).map(String::as_str)
                }
            }
        }

        pub mod edge {
            use std::collections::HashMap;

            use crate::graph::extend_attrs;

            /// A connection between two nodes, e.g. `a -- b [color="green"]`.
            #[derive(Debug, Clone, PartialEq, Eq)]
            pub struct Edge {
                from: String,
                to: String,
                attrs: HashMap<String, String>,
            }

            impl Edge {
                /// Creates an edge between the nodes named `from` and `to`,
                /// with no attributes.
                pub fn new(from: &str, to: &str) -> Self {
                    Self {
                        from: from.to_string(),
                        to: to.to_string(),
                        attrs: HashMap::new(),
                    }
                }

                /// Adds attributes to the edge, overwriting existing values
                /// stored under the same keys.
                #[must_use]
                pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
                    extend_attrs(&mut self.attrs, attrs);
                    self
                }

                /// Returns the name of the node the edge starts at.
                pub fn from(&self) -> &str {
                    &self.from
                }

                /// Returns the name of the node the edge ends at.
                pub fn to(&self) -> &str {
                    &self.to
                }

                /// Returns the value of the attribute `key`, if it is set.
                pub fn attr(&self, key: &str) -> Option<&str> {
                    self.attrs.get(key).map(String::as_str)
                }
            }
        }
    }

    /// A graph made of nodes, edges and graph-level attributes.
    ///
    /// ```
    /// use dot_dsl::graph::graph_items::edge::Edge;
    /// use dot_dsl::graph::graph_items::node::Node;
    /// use dot_dsl::graph::Graph;
    ///
    /// // graph {
    /// //     graph [bgcolor="yellow"]
    /// //     a [color="red"]
    /// //     b [color="blue"]
    /// //     a -- b [color="green"]
    /// // }
    /// let graph = Graph::new()
    ///     .with_attrs(&[("bgcolor", "yellow")])
    ///     .with_nodes(&[
    ///         Node::new("a").with_attrs(&[("color", "red")]),
    ///         Node::new("b").with_attrs(&[("color", "blue")]),
    ///     ])
    ///     .with_edges(&[Edge::new("a", "b").with_attrs(&[("color", "green")])]);
    ///
    /// assert_eq!(graph.attr("bgcolor"), Some("yellow"));
    /// assert_eq!(graph.node("b").and_then(|b| b.attr("color")), Some("blue"));
    /// assert_eq!(graph.edges[0].attr("color"), Some("green"));
    /// ```
    #[derive(Debug, Clone, Default, PartialEq, Eq)]
    pub struct Graph {
        pub nodes: Vec<Node>,
        pub edges: Vec<Edge>,
        pub attrs: HashMap<String, String>,
    }

    impl Graph {
        /// Creates an empty graph: no nodes, no edges, no attributes.
        pub fn new() -> Self {
            Self::default()
        }

        /// Adds the given nodes to the graph.
        #[must_use]
        pub fn with_nodes(mut self, nodes: &[Node]) -> Self {
            self.nodes.extend_from_slice(nodes);
            self
        }

        /// Adds the given edges to the graph.
        #[must_use]
        pub fn with_edges(mut self, edges: &[Edge]) -> Self {
            self.edges.extend_from_slice(edges);
            self
        }

        /// Adds graph-level attributes, overwriting existing values stored
        /// under the same keys.
        #[must_use]
        pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
            extend_attrs(&mut self.attrs, attrs);
            self
        }

        /// Returns the first node with the given name, if any.
        pub fn node(&self, name: &str) -> Option<&Node> {
            self.nodes.iter().find(|node| node.name() == name)
        }

        /// Returns the value of the graph-level attribute `key`, if it is set.
        pub fn attr(&self, key: &str) -> Option<&str> {
            self.attrs.get(key).map(String::as_str)
        }
    }
}
