//
// Implementation of the 'Promises' exercise.
//
// The combinators below are built with nothing but the `Promise` constructor,
// `Promise.resolve` (so plain values are accepted as well as promises) and
// `.then`: the built-in `Promise.all`, `Promise.allSettled`, `Promise.race`
// and `Promise.any` methods are deliberately not used.
//
// Following the exercise's conventions, every combinator:
//   - resolves with `undefined` when called without any argument;
//   - resolves with an empty array when given an empty list of promises.
//

/**
 * Turns a function following the "callback pattern" (an error-first callback
 * as its last argument) into a function returning a Promise.
 *
 * @param {Function} fn function whose last parameter is a `(error, data)` callback
 * @returns {Function} function taking the same arguments (minus the callback)
 *   and returning a Promise of `data`
 */
export const promisify = (fn) => {
  if (typeof fn !== 'function') {
    throw new TypeError('promisify expects a function');
  }

  return function promisified(...args) {
    return new Promise((resolve, reject) => {
      fn.call(this, ...args, (error, data) => {
        if (error) {
          reject(error);
        } else {
          resolve(data);
        }
      });
    });
  };
};

/**
 * Resolves once every given promise has resolved, with their values in the
 * order the promises were passed in. Rejects as soon as one of them rejects,
 * with that error.
 *
 * @param {Iterable<*>} [promises]
 * @returns {Promise<Array<*>|undefined>}
 */
export const all = (promises) => {
  if (promises === undefined) {
    return Promise.resolve();
  }

  return new Promise((resolve, reject) => {
    const items = Array.from(promises);
    const values = new Array(items.length);
    let pending = items.length;

    if (pending === 0) {
      resolve(values);
      return;
    }

    items.forEach((item, index) => {
      Promise.resolve(item).then((value) => {
        values[index] = value;
        pending -= 1;
        if (pending === 0) {
          resolve(values);
        }
      }, reject);
    });
  });
};

/**
 * Resolves once every given promise has settled (resolved or rejected), with
 * each resolved value or rejection error in the order the promises were
 * passed in. A failing promise does not make it reject.
 *
 * @param {Iterable<*>} [promises]
 * @returns {Promise<Array<*>|undefined>}
 */
export const allSettled = (promises) => {
  if (promises === undefined) {
    return Promise.resolve();
  }

  return new Promise((resolve) => {
    const items = Array.from(promises);
    const outcomes = new Array(items.length);
    let pending = items.length;

    if (pending === 0) {
      resolve(outcomes);
      return;
    }

    const settle = (index, outcome) => {
      outcomes[index] = outcome;
      pending -= 1;
      if (pending === 0) {
        resolve(outcomes);
      }
    };

    items.forEach((item, index) => {
      Promise.resolve(item).then(
        (value) => settle(index, value),
        (error) => settle(index, error),
      );
    });
  });
};

/**
 * Settles like the first given promise to settle: resolves with its value if
 * it resolved, rejects with its error if it rejected.
 *
 * @param {Iterable<*>} [promises]
 * @returns {Promise<*>}
 */
export const race = (promises) => {
  if (promises === undefined) {
    return Promise.resolve();
  }

  return new Promise((resolve, reject) => {
    const items = Array.from(promises);

    if (items.length === 0) {
      resolve([]);
      return;
    }

    items.forEach((item) => {
      Promise.resolve(item).then(resolve, reject);
    });
  });
};

/**
 * Resolves with the value of the first given promise to resolve. Rejects only
 * once all of them have rejected, with the array of their errors (in the
 * order the promises were passed in).
 *
 * @param {Iterable<*>} [promises]
 * @returns {Promise<*>}
 */
export const any = (promises) => {
  if (promises === undefined) {
    return Promise.resolve();
  }

  return new Promise((resolve, reject) => {
    const items = Array.from(promises);
    const errors = new Array(items.length);
    let pending = items.length;

    if (pending === 0) {
      resolve([]);
      return;
    }

    items.forEach((item, index) => {
      Promise.resolve(item).then(resolve, (error) => {
        errors[index] = error;
        pending -= 1;
        if (pending === 0) {
          reject(errors);
        }
      });
    });
  });
};
```

