// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

type Link<T> = Option<NonNull<Node<T>>>;

struct Node<T> {
    elem: T,
    prev: Link<T>,
    next: Link<T>,
}

// Invariants:
// - every node pointer reachable from head/tail was created by Box::leak and is
//   owned uniquely by this list
// - head.prev == None, tail.next == None, links are mutually consistent
// - len equals the number of nodes; head/tail are None iff len == 0
pub struct LinkedList<T> {
    head: Link<T>,
    tail: Link<T>,
    len: usize,
    _marker: PhantomData<Box<Node<T>>>,
}

// SAFETY: the list owns its T values just like a Box/Vec would.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: &LinkedList only gives out &T.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    // None only if the list is empty
    cur: Link<T>,
}

pub struct Iter<'a, T> {
    next: Link<T>,
    _marker: PhantomData<&'a T>,
}

impl<T> Default for LinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let cur = self.head;
        Cursor { list: self, cur }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let cur = self.tail;
        Cursor { list: self, cur }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.head,
            _marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut link = self.head;
        while let Some(node) = link {
            // SAFETY: each node was created via Box::leak and is owned only by
            // this list; we free each exactly once.
            let boxed = unsafe { Box::from_raw(node.as_ptr()) };
            link = boxed.next;
        }
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: cur points to a live node of the list we mutably borrow;
        // the returned reference is tied to &mut self.
        self.cur.map(|n| unsafe { &mut (*n.as_ptr()).elem })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let cur = self.cur?;
        // SAFETY: cur is a live node of the list.
        let next = unsafe { (*cur.as_ptr()).next }?;
        self.cur = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let cur = self.cur?;
        // SAFETY: cur is a live node of the list.
        let prev = unsafe { (*cur.as_ptr()).prev }?;
        self.cur = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let cur = self.cur?;
        // SAFETY: cur is a live, uniquely owned node; we unlink it from its
        // neighbours (also live) and then reclaim its Box exactly once.
        unsafe {
            let boxed = Box::from_raw(cur.as_ptr());
            match boxed.prev {
                Some(p) => (*p.as_ptr()).next = boxed.next,
                None => self.list.head = boxed.next,
            }
            match boxed.next {
                Some(n) => (*n.as_ptr()).prev = boxed.prev,
                None => self.list.tail = boxed.prev,
            }
            self.list.len -= 1;
            self.cur = boxed.next.or(boxed.prev);
            Some(boxed.elem)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        let node = NonNull::from(Box::leak(Box::new(Node {
            elem: element,
            prev: self.cur,
            next: None,
        })));
        // SAFETY: cur and its next are live nodes; node is freshly allocated
        // and now owned by the list.
        unsafe {
            match self.cur {
                None => {
                    self.list.head = Some(node);
                    self.list.tail = Some(node);
                    self.cur = Some(node);
                }
                Some(cur) => {
                    let next = (*cur.as_ptr()).next;
                    (*node.as_ptr()).next = next;
                    (*cur.as_ptr()).next = Some(node);
                    match next {
                        Some(n) => (*n.as_ptr()).prev = Some(node),
                        None => self.list.tail = Some(node),
                    }
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let node = NonNull::from(Box::leak(Box::new(Node {
            elem: element,
            prev: None,
            next: self.cur,
        })));
        // SAFETY: cur and its prev are live nodes; node is freshly allocated
        // and now owned by the list.
        unsafe {
            match self.cur {
                None => {
                    self.list.head = Some(node);
                    self.list.tail = Some(node);
                    self.cur = Some(node);
                }
                Some(cur) => {
                    let prev = (*cur.as_ptr()).prev;
                    (*node.as_ptr()).prev = prev;
                    (*cur.as_ptr()).prev = Some(node);
                    match prev {
                        Some(p) => (*p.as_ptr()).next = Some(node),
                        None => self.list.head = Some(node),
                    }
                }
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: the list is immutably borrowed for 'a, so the node stays
        // alive and unmodified for 'a.
        unsafe {
            let r = &*node.as_ptr();
            self.next = r.next;
            Some(&r.elem)
        }
    }
}
