// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

// # Safety-critical invariants
//
// For every `LinkedList<T>`:
//
// 1. Every node reachable from `front` / `back` was allocated with `Box::new`
//    and converted into a raw pointer (via `Box::leak`). The list is the
//    unique owner of all of its nodes; no node is shared between lists.
// 2. `front.is_none() == back.is_none() == (len == 0)`.
// 3. The links are consistent: for every node `n` in the list,
//    - `n.next` is `Some(m)` iff `m` is the node directly after `n`
//      (and then `m.prev == Some(n)`), and `None` iff `n` is the back node;
//    - `n.prev` is `Some(m)` iff `m` is the node directly before `n`
//      (and then `m.next == Some(n)`), and `None` iff `n` is the front node.
// 4. `len` equals the number of nodes in the list.
//
// For every `Cursor<'a, T>`:
//
// 5. `cur` is `None` iff the list is empty; otherwise it points to a node that
//    is currently part of `list`.
//
// For every `Iter<'a, T>`:
//
// 6. `next` is either `None` or points to a node of a list that is immutably
//    borrowed for `'a`, so the node stays alive and unmodified for `'a`.
//
// All raw pointer accesses below rely on these invariants, and every function
// that modifies the list re-establishes them before returning.

type Link<T> = Option<NonNull<Node<T>>>;

struct Node<T> {
    elem: T,
    prev: Link<T>,
    next: Link<T>,
}

impl<T> Node<T> {
    /// Allocate a new node on the heap and return an owning raw pointer to it.
    /// The caller is responsible for eventually freeing it with `Box::from_raw`
    /// (which the list does in `Cursor::take`).
    fn new_ptr(elem: T, prev: Link<T>, next: Link<T>) -> NonNull<Node<T>> {
        let boxed = Box::new(Node { elem, prev, next });
        NonNull::from(Box::leak(boxed))
    }
}

pub struct LinkedList<T> {
    front: Link<T>,
    back: Link<T>,
    len: usize,
    // We logically own boxed nodes containing `T`s.
    // This makes the list covariant over `T` and tells drop-check that we drop `T`s.
    _marker: PhantomData<Box<Node<T>>>,
}

pub struct Cursor<'a, T> {
    cur: Link<T>,
    list: &'a mut LinkedList<T>,
}

pub struct Iter<'a, T> {
    next: Link<T>,
    _marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            front: None,
            back: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        Cursor {
            cur: self.front,
            list: self,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        Cursor {
            cur: self.back,
            list: self,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.front,
            _marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Iteratively remove (and drop) every element. Since the cursor starts
        // at the front, `take` always moves to the next element, until the list
        // is empty. This avoids recursion, so long lists can't overflow the stack.
        let mut cursor = self.cursor_front();
        while cursor.take().is_some() {}
    }
}

// SAFETY: `LinkedList<T>` owns its `T`s exactly like `Box<T>` or `Vec<T>` do.
// The raw pointers are never shared with anything outside the list (other than
// borrows tied to the list's lifetime), so sending the list to another thread
// just moves ownership of the `T`s, which is fine if `T: Send`.
unsafe impl<T: Send> Send for LinkedList<T> {}

// SAFETY: Through a `&LinkedList<T>` one can only obtain `&T` (via `iter`),
// and no interior mutability is involved. Thus sharing the list across threads
// is fine if sharing `T` is, i.e. `T: Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: A cursor behaves like a `&mut LinkedList<T>`, which is `Send` iff
// `LinkedList<T>: Send`, i.e. `T: Send`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}

// SAFETY: A cursor behaves like a `&mut LinkedList<T>`, which is `Sync` iff
// `LinkedList<T>: Sync`, i.e. `T: Sync`. Through `&Cursor` nothing can be accessed.
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: `Iter` behaves like a `&'a T`, which is `Send` iff `T: Sync`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}

// SAFETY: `Iter` behaves like a `&'a T`, which is `Sync` iff `T: Sync`.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        self.cur.map(|node| {
            // SAFETY: By invariant 5, `node` points to a live node owned by
            // `self.list`. We hold the list's unique `&mut` borrow, and the
            // returned reference borrows `self` mutably, so no other reference
            // to this element can exist while it is alive.
            unsafe { &mut (*node.as_ptr()).elem }
        })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let cur = self.cur?;
        // SAFETY: By invariant 5, `cur` points to a live node of the list,
        // so reading its `next` link is valid.
        let next = unsafe { (*cur.as_ptr()).next }?;
        self.cur = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let cur = self.cur?;
        // SAFETY: By invariant 5, `cur` points to a live node of the list,
        // so reading its `prev` link is valid.
        let prev = unsafe { (*cur.as_ptr()).prev }?;
        self.cur = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.cur?;

        // SAFETY: By invariant 5, `node` points to a live node of the list.
        let (prev, next) = unsafe { ((*node.as_ptr()).prev, (*node.as_ptr()).next) };

        // Unlink the node from its neighbours (or the list ends).
        match prev {
            // SAFETY: By invariant 3, `p` is a live node of the list distinct
            // from `node`; we have exclusive access to the list.
            Some(p) => unsafe { (*p.as_ptr()).next = next },
            None => self.list.front = next,
        }
        match next {
            // SAFETY: By invariant 3, `n` is a live node of the list distinct
            // from `node`; we have exclusive access to the list.
            Some(n) => unsafe { (*n.as_ptr()).prev = prev },
            None => self.list.back = prev,
        }
        self.list.len -= 1;

        // Move the cursor; `None` only if the list is now empty (invariant 5).
        self.cur = next.or(prev);

        // SAFETY: `node` was allocated via `Box` (invariant 1) and is now
        // completely unlinked from the list, so nothing else refers to it.
        // We therefore reclaim unique ownership and free it exactly once.
        let boxed = unsafe { Box::from_raw(node.as_ptr()) };
        Some(boxed.elem)
    }

    pub fn insert_after(&mut self, element: T) {
        match self.cur {
            None => self.insert_into_empty(element),
            Some(cur) => {
                // SAFETY: By invariant 5, `cur` points to a live node of the list.
                let next = unsafe { (*cur.as_ptr()).next };
                let new = Node::new_ptr(element, Some(cur), next);

                // SAFETY: `cur` is a live node of the list and we have exclusive
                // access to the list.
                unsafe { (*cur.as_ptr()).next = Some(new) };
                match next {
                    // SAFETY: By invariant 3, `n` is a live node of the list.
                    Some(n) => unsafe { (*n.as_ptr()).prev = Some(new) },
                    None => self.list.back = Some(new),
                }
                self.list.len += 1;
            }
        }
    }

    pub fn insert_before(&mut self, element: T) {
        match self.cur {
            None => self.insert_into_empty(element),
            Some(cur) => {
                // SAFETY: By invariant 5, `cur` points to a live node of the list.
                let prev = unsafe { (*cur.as_ptr()).prev };
                let new = Node::new_ptr(element, prev, Some(cur));

                // SAFETY: `cur` is a live node of the list and we have exclusive
                // access to the list.
                unsafe { (*cur.as_ptr()).prev = Some(new) };
                match prev {
                    // SAFETY: By invariant 3, `p` is a live node of the list.
                    Some(p) => unsafe { (*p.as_ptr()).next = Some(new) },
                    None => self.list.front = Some(new),
                }
                self.list.len += 1;
            }
        }
    }

    /// Insert the first element into an empty list and position the cursor on it.
    /// Only called when `self.cur` is `None`, which by invariant 5 means the list is empty.
    fn insert_into_empty(&mut self, element: T) {
        debug_assert!(self.list.is_empty());
        let new = Node::new_ptr(element, None, None);
        self.list.front = Some(new);
        self.list.back = Some(new);
        self.list.len = 1;
        self.cur = Some(new);
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: By invariant 6, `node` points to a live node of a list that is
        // immutably borrowed for `'a`, so the node outlives `'a` and nobody can
        // mutate it during `'a`. Handing out `&'a T` is therefore sound.
        unsafe {
            let ptr = node.as_ptr();
            self.next = (*ptr).next;
            Some(&(*ptr).elem)
        }
    }
}
