// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

/// A pointer to a neighbouring node, or `None` at either end of the list.
type Link<T> = Option<NonNull<Node<T>>>;

struct Node<T> {
    element: T,
    prev: Link<T>,
    next: Link<T>,
}

/// A doubly linked list.
///
/// # Safety invariants
///
/// All `unsafe` code in this module relies on the following invariants. Every
/// method restores them before it returns and none can panic while they are
/// temporarily broken, so they always hold when safe code can observe the list.
///
/// - (L1) `front.is_none()`, `back.is_none()` and `len == 0` are either all
///   true or all false.
/// - (L2) Every node was allocated with `Box::new` and turned into a pointer
///   with `Box::leak`. The list is the unique owner of its nodes: they are not
///   shared with anything else and each one is freed exactly once, by turning
///   it back into a `Box` after it has been unlinked from the list.
/// - (L3) The links are consistent: following `next` from `front` visits
///   exactly `len` distinct nodes and ends at `back`. `front.prev` and
///   `back.next` are `None`, and for any two nodes `a` and `b`,
///   `a.next == Some(b)` holds if and only if `b.prev == Some(a)` does.
///   In particular, every neighbour of a node of the list is a node of the list.
/// - (L4) Nodes are only accessed through a borrow of the list owning them.
///   Through a shared borrow (`&LinkedList`, `Iter`) they are only read,
///   mutation requires an exclusive borrow (`&mut LinkedList`, `Cursor`).
///   This way, the borrow checker ensures that references to elements can
///   neither outlive their nodes nor alias a mutable reference.
///
/// # Variance
///
/// `NonNull<_>` and `PhantomData<_>` are covariant, so `LinkedList<T>` is
/// covariant in `T`. That is sound for the same reasons as for `Box<T>`: the
/// list owns its elements and can only be mutated through `&mut`, which is
/// invariant again.
pub struct LinkedList<T> {
    front: Link<T>,
    back: Link<T>,
    len: usize,
    /// Signals to the drop checker that the list owns (boxed nodes containing)
    /// values of type `T` and may drop them.
    _marker: PhantomData<Box<Node<T>>>,
}

/// A cursor with exclusive access to a list, positioned on one of its elements.
///
/// # Safety invariant
///
/// - (C1) `current` is `None` if and only if the list is empty. Otherwise, it
///   points to a node of `list`.
pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Link<T>,
}

/// An iterator over shared references to the elements of a list, from front to back.
///
/// # Safety invariant
///
/// - (I1) `next` is either `None` or points to a node of a list that is borrowed
///   immutably for `'a`. Therefore, that node stays alive and is not modified
///   for at least `'a` (L4).
pub struct Iter<'a, T> {
    next: Link<T>,
    _marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            front: None,
            back: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    // The length is updated on every insertion and removal, so this is O(1).
    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        // Upholds C1: `front` is `None` iff the list is empty (L1),
        // otherwise it is a node of the list (L3).
        let current = self.front;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        // Upholds C1: `back` is `None` iff the list is empty (L1),
        // otherwise it is a node of the list (L3).
        let current = self.back;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        // Upholds I1: `front` is either `None` or a node of `self`, which stays
        // immutably borrowed for as long as the iterator lives.
        Iter {
            next: self.front,
            _marker: PhantomData,
        }
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: By C1, `current` points to a live node of the list, to which the
        // cursor has exclusive access. The returned reference mutably borrows the
        // cursor, so while it exists, the node can neither be accessed through the
        // cursor nor be freed.
        Some(unsafe { &mut (*current.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: By C1, `current` points to a live node of the list, to which the
        // cursor has exclusive access. We only copy one of its links.
        let next = unsafe { (*current.as_ptr()).next }?;
        // Upholds C1: by L3, the successor of a node of the list is a node of the list.
        self.current = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: By C1, `current` points to a live node of the list, to which the
        // cursor has exclusive access. We only copy one of its links.
        let prev = unsafe { (*current.as_ptr()).prev }?;
        // Upholds C1: by L3, the predecessor of a node of the list is a node of the list.
        self.current = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;
        // SAFETY: By C1, `node` points to a live node of the list, to which the
        // cursor has exclusive access. We only copy its links.
        let (prev, next) = unsafe { ((*node.as_ptr()).prev, (*node.as_ptr()).next) };

        // Unlink `node` by letting its neighbours (or the ends of the list) skip it.
        match prev {
            // SAFETY: By L3, the predecessor of a node of the list is a live node
            // of the list as well, to which the cursor has exclusive access.
            Some(prev) => unsafe { (*prev.as_ptr()).next = next },
            // By L3, `node` was the front.
            None => self.list.front = next,
        }
        match next {
            // SAFETY: By L3, the successor of a node of the list is a live node
            // of the list as well, to which the cursor has exclusive access.
            Some(next) => unsafe { (*next.as_ptr()).prev = prev },
            // By L3, `node` was the back.
            None => self.list.back = prev,
        }
        // Can't underflow: the list contained at least `node`.
        self.list.len -= 1;
        // Upholds C1: if `node` had no neighbours, it was the only node, so the
        // list is empty now.
        self.current = next.or(prev);

        // SAFETY: By L2, `node` was allocated with `Box` and is uniquely owned by
        // the list. It has just been unlinked, so neither the list nor the cursor
        // refer to it anymore. Hence we can take back its ownership here, and it is
        // freed exactly once, when the box is dropped at the end of this function.
        let node = unsafe { Box::from_raw(node.as_ptr()) };
        Some(node.element)
    }

    /// Insert `element` directly after the current element. The cursor stays where
    /// it is, unless the list was empty, in which case it moves to the new element.
    pub fn insert_after(&mut self, element: T) {
        let (prev, next) = match self.current {
            // SAFETY: By C1, `current` points to a live node of the list, to which
            // the cursor has exclusive access. We only copy one of its links.
            Some(current) => (Some(current), unsafe { (*current.as_ptr()).next }),
            // By C1, the list is empty.
            None => (None, None),
        };
        // SAFETY: `prev` and `next` are adjacent: Either the list is empty and both
        // are `None` (so `next` is the list's `front`), or `prev` is a node of the
        // list (C1) and `next` is its successor.
        unsafe { self.insert_between(prev, next, element) }
    }

    /// Insert `element` directly before the current element. The cursor stays where
    /// it is, unless the list was empty, in which case it moves to the new element.
    pub fn insert_before(&mut self, element: T) {
        let (prev, next) = match self.current {
            // SAFETY: By C1, `current` points to a live node of the list, to which
            // the cursor has exclusive access. We only copy one of its links.
            Some(current) => (unsafe { (*current.as_ptr()).prev }, Some(current)),
            // By C1, the list is empty.
            None => (None, None),
        };
        // SAFETY: `prev` and `next` are adjacent: Either the list is empty and both
        // are `None` (so `next` is the list's `front`), or `next` is the current node
        // and `prev` its predecessor. If that predecessor is `None`, the current node
        // is the `front` (L3); otherwise it is a node of the list whose successor is
        // the current node (L3).
        unsafe { self.insert_between(prev, next, element) }
    }

    /// Allocate a new node holding `element` and link it into the list between
    /// `prev` and `next`. If the cursor isn't positioned on an element (which is
    /// only possible if the list was empty), it moves to the new node.
    ///
    /// # Safety
    ///
    /// `prev` and `next` must be adjacent positions in `self.list`, i.e. either
    /// - `prev` is `None` and `next` is the list's `front`, or
    /// - `prev` is `Some(node)` for a node of the list and `next` is that node's
    ///   `next` link.
    unsafe fn insert_between(&mut self, prev: Link<T>, next: Link<T>, element: T) {
        // Upholds L2: the node is allocated with `Box`, the list becomes its unique owner.
        let node = NonNull::from(Box::leak(Box::new(Node {
            element,
            prev,
            next,
        })));

        match prev {
            // SAFETY: The caller guarantees that `prev` is a node of the list, so it
            // is alive (L2) and the cursor has exclusive access to it.
            Some(prev) => unsafe { (*prev.as_ptr()).next = Some(node) },
            // The caller guarantees that `next` was the front.
            None => self.list.front = Some(node),
        }
        match next {
            // SAFETY: The caller guarantees that `next` is the front or the successor
            // of a node of the list. Either way it is a live node of the list (L1-L3),
            // to which the cursor has exclusive access.
            Some(next) => unsafe { (*next.as_ptr()).prev = Some(node) },
            // `prev` was the back: either it is `None`, so the front was `None` as
            // well and the list was empty (L1), or it is a node without successor (L3).
            None => self.list.back = Some(node),
        }
        self.list.len += 1;

        // Upholds C1: the list isn't empty anymore, so the cursor has to point to a node.
        if self.current.is_none() {
            self.current = Some(node);
        }
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: By I1, `node` points to a node of a list that is immutably borrowed
        // for `'a`, so the node stays alive and unmodified for at least `'a` (L4).
        // Thus a shared reference to it may live for `'a`.
        let node: &'a Node<T> = unsafe { &*node.as_ptr() };
        // Upholds I1: by L3, the successor is either `None` or a node of the same list.
        self.next = node.next;
        Some(&node.element)
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Take out (and thereby free) the nodes one by one, front to back.
        // Doing this iteratively means that even very long lists can't overflow
        // the stack, and since it goes through the cursor, the list stays
        // consistent at every step (if an element's destructor panics, the
        // remaining nodes are merely leaked, which is safe).
        let mut cursor = self.cursor_front();
        while cursor.take().is_some() {}
    }
}

// SAFETY: A `LinkedList<T>` owns its elements just like a `Vec<T>` or a `Box<T>`
// does: its nodes aren't shared with anything else (L2), so sending the list to
// another thread merely moves the ownership of the `T`s to that thread. That is
// sound if `T: Send`.
unsafe impl<T: Send> Send for LinkedList<T> {}

// SAFETY: Through a `&LinkedList<T>`, nodes are only read (L4) and at most `&T`s
// are handed out. There is no interior mutability, so sharing the list between
// threads is sound if `T: Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: A `Cursor<'_, T>` is effectively a `&mut LinkedList<T>` (it accesses the
// nodes only through its exclusive borrow of the list). `&mut LinkedList<T>` is
// `Send` if `LinkedList<T>: Send`, i.e. if `T: Send`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}

// SAFETY: A `Cursor<'_, T>` is effectively a `&mut LinkedList<T>`, which is `Sync`
// if `LinkedList<T>: Sync`, i.e. if `T: Sync`. (All of its methods even require
// `&mut self`, so nothing can be done with a shared `&Cursor` at all.)
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: An `Iter<'_, T>` is effectively a `&LinkedList<T>` that only reads nodes
// and hands out `&T`s. `&LinkedList<T>` is `Send` if `LinkedList<T>: Sync`, i.e.
// if `T: Sync`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}

// SAFETY: An `Iter<'_, T>` is effectively a `&LinkedList<T>`, which is `Sync` if
// `LinkedList<T>: Sync`, i.e. if `T: Sync`.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}
