I'll implement the three functions using Go's standard library:

- **`Verse(n)`** returns the verse for `n` bottles, ending with a newline. It returns an error if `n` is outside 0–99.
  - The special cases are 2, 1 and 0. These cover "1 bottle" (singular), "Take it down", "no more bottles" and "Go to the store and buy some more".
  - All other verses use the general format.
- **`Verses(start, stop)`** returns verses from `start` down to `stop`. Each verse is followed by a blank line. It returns an error if either bound is invalid, or if `start < stop`.
- **`Song()`** returns `Verses(99, 0)`.

beer_song.go
```go
package beer

import (
	"fmt"
	"strings"
)

// Song returns the full lyrics of 99 Bottles of Beer on the Wall.
func Song() string {
	song, _ := Verses(99, 0)
	return song
}

// Verses returns the verses from start down to stop (inclusive),
// each followed by a blank line.
func Verses(start, stop int) (string, error) {
	if start < 0 || start > 99 {
		return "", fmt.Errorf("invalid start verse %d", start)
	}
	if stop < 0 || stop > 99 {
		return "", fmt.Errorf("invalid stop verse %d", stop)
	}
	if start < stop {
		return "", fmt.Errorf("start verse %d is less than stop verse %d", start, stop)
	}

	var sb strings.Builder
	for i := start; i >= stop; i-- {
		v, err := Verse(i)
		if err != nil {
			return "", err
		}
		sb.WriteString(v)
		sb.WriteString("\n")
	}
	return sb.String(), nil
}

// Verse returns the verse for n bottles.
func Verse(n int) (string, error) {
	switch {
	case n < 0 || n > 99:
		return "", fmt.Errorf("invalid verse %d", n)
	case n == 0:
		return "No more bottles of beer on the wall, no more bottles of beer.\n" +
			"Go to the store and buy some more, 99 bottles of beer on the wall.\n", nil
	case n == 1:
		return "1 bottle of beer on the wall, 1 bottle of beer.\n" +
			"Take it down and pass it around, no more bottles of beer on the wall.\n", nil
	case n == 2:
		return "2 bottles of beer on the wall, 2 bottles of beer.\n" +
			"Take one down and pass it around, 1 bottle of beer on the wall.\n", nil
	default:
		return fmt.Sprintf("%d bottles of beer on the wall, %d bottles of beer.\n"+
			"Take one down and pass it around, %d bottles of beer on the wall.\n", n, n, n-1), nil
	}
}
