The verses differ for 2, 1 and 0. To keep `Verse` readable, those differences are handled by a few small helpers:

- **`bottles(n)`** handles "no more", "1 bottle" and "N bottles".
- **`action(n)`** chooses the second line's opening ("Take one down", "Take it down" or "Go to the store").
- **`next(n)`** wraps from 0 back to 99.

beer_song.go
```go
package beer

import (
	"errors"
	"fmt"
	"strings"
)

// Song returns the full lyrics from 99 down to 0.
func Song() string {
	s, _ := Verses(99, 0)
	return s
}

// Verses returns the verses from start down to stop, each followed by a blank line.
func Verses(start, stop int) (string, error) {
	if start < 0 || start > 99 || stop < 0 || stop > 99 {
		return "", errors.New("verse out of range")
	}
	if start < stop {
		return "", errors.New("start must be greater than or equal to stop")
	}
	var sb strings.Builder
	for i := start; i >= stop; i-- {
		v, _ := Verse(i)
		sb.WriteString(v)
		sb.WriteString("\n")
	}
	return sb.String(), nil
}

// Verse returns a single verse for n bottles.
func Verse(n int) (string, error) {
	if n < 0 || n > 99 {
		return "", errors.New("verse out of range")
	}
	return fmt.Sprintf("%s of beer on the wall, %s of beer.\n%s, %s of beer on the wall.\n",
		capitalize(bottles(n)), bottles(n), action(n), bottles(next(n))), nil
}

func bottles(n int) string {
	switch n {
	case 0:
		return "no more bottles"
	case 1:
		return "1 bottle"
	default:
		return fmt.Sprintf("%d bottles", n)
	}
}

func action(n int) string {
	switch n {
	case 0:
		return "Go to the store and buy some more"
	case 1:
		return "Take it down and pass it around"
	default:
		return "Take one down and pass it around"
	}
}

func next(n int) int {
	if n == 0 {
		return 99
	}
	return n - 1
}

func capitalize(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}
```

