#include "queen_attack.h"

#include <cstdlib>
#include <stdexcept>

namespace queen_attack {

namespace {

bool is_valid(const chess_board::position& pos)
{
    return pos.first >= 0 && pos.first < 8 && pos.second >= 0 && pos.second < 8;
}

}  // namespace

chess_board::chess_board()
    : chess_board(std::make_pair(0, 3), std::make_pair(7, 3))
{
}

chess_board::chess_board(position white, position black)
    : white_(white), black_(black)
{
    if (!is_valid(white_) || !is_valid(black_)) {
        throw std::domain_error("Queen position must be on the board");
    }
    if (white_ == black_) {
        throw std::domain_error("Queens cannot occupy the same position");
    }
}

chess_board::position chess_board::white() const
{
    return white_;
}

chess_board::position chess_board::black() const
{
    return black_;
}

bool chess_board::can_attack() const
{
    const int row_diff = std::abs(white_.first - black_.first);
    const int col_diff = std::abs(white_.second - black_.second);
    return row_diff == 0 || col_diff == 0 || row_diff == col_diff;
}

chess_board::operator std::string() const
{
    std::string result;
    for (int row = 0; row < 8; ++row) {
        for (int col = 0; col < 8; ++col) {
            if (col > 0) {
                result += ' ';
            }
            const position current{row, col};
            if (current == white_) {
                result += 'W';
            } else if (current == black_) {
                result += 'B';
            } else {
                result += '_';
            }
        }
        result += '\n';
    }
    return result;
}

}  // namespace queen_attack
