// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

// # Safety-critical invariants
//
// 1. Every node reachable from a `LinkedList` was allocated via `Box::new`
//    (see `Node::alloc`) and is owned by exactly one list. It is freed exactly
//    once, via `Box::from_raw`, when it is removed from the list (`Cursor::take`).
// 2. Link consistency: `head` is `None` iff `tail` is `None` iff `len == 0`.
//    `head.prev` and `tail.next` are `None`. For all nodes `a`, `b`:
//    `a.next == Some(b)` iff `b.prev == Some(a)`. `len` equals the number of nodes.
// 3. A `Cursor`'s `cur` is `None` iff the borrowed list is empty, otherwise it
//    points at a node of that list. Since the cursor holds `&mut LinkedList`,
//    no other access to the list (and its nodes) can happen while it lives.
// 4. An `Iter` borrows the list immutably, so no node can be removed or
//    mutated while the iterator lives; all pointers it follows stay valid.

type Link<T> = Option<NonNull<Node<T>>>;

struct Node<T> {
    element: T,
    prev: Link<T>,
    next: Link<T>,
}

impl<T> Node<T> {
    /// Allocate a new node on the heap and return an owning raw pointer to it.
    /// The caller is responsible for eventually freeing it via `Box::from_raw`.
    fn alloc(element: T, prev: Link<T>, next: Link<T>) -> NonNull<Node<T>> {
        NonNull::from(Box::leak(Box::new(Node {
            element,
            prev,
            next,
        })))
    }
}

pub struct LinkedList<T> {
    head: Link<T>,
    tail: Link<T>,
    len: usize,
    // We logically own the nodes (and thus values of type `T`).
    // This also keeps `LinkedList<T>` covariant over `T`.
    _marker: PhantomData<Box<Node<T>>>,
}

pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    cur: Link<T>,
}

pub struct Iter<'a, T> {
    next: Link<T>,
    _marker: PhantomData<&'a T>,
}

// SAFETY: `LinkedList<T>` owns its `T`s just like `Vec<T>` or `Box<T>`;
// sending the list sends the `T`s, which is fine if `T: Send`.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: a `&LinkedList<T>` only gives out `&T`, so sharing it is fine if `T: Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: a cursor behaves like `&mut LinkedList<T>`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
// SAFETY: through `&Cursor` nothing can be accessed (all methods take `&mut self`),
// requiring `T: Sync` is conservative and matches `&mut LinkedList<T>`.
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: an `Iter` behaves like `&LinkedList<T>` / `&T`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
// SAFETY: same as above.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

impl<T> Default for LinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let cur = self.head;
        Cursor { list: self, cur }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let cur = self.tail;
        Cursor { list: self, cur }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.head,
            _marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cursor = self.cursor_front();
        while cursor.take().is_some() {}
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: by invariant 3, `cur` points to a live node of the list we
        // borrow mutably. The returned reference borrows `self` mutably, so no
        // other access to the node can happen while it lives.
        self.cur.map(|node| unsafe { &mut (*node.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let cur = self.cur?;
        // SAFETY: `cur` points to a live node of the list (invariant 3).
        let next = unsafe { (*cur.as_ptr()).next }?;
        self.cur = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let cur = self.cur?;
        // SAFETY: `cur` points to a live node of the list (invariant 3).
        let prev = unsafe { (*cur.as_ptr()).prev }?;
        self.cur = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let cur = self.cur?;
        // SAFETY: `cur` was allocated via `Box` (invariant 1) and is a live
        // node of this list (invariant 3). We unlink it below before anyone can
        // observe the dangling pointer, so it is freed exactly once.
        let node = unsafe { Box::from_raw(cur.as_ptr()) };
        let Node {
            element,
            prev,
            next,
        } = *node;

        match prev {
            // SAFETY: `prev` is a live neighbor node of the list (invariant 2).
            Some(p) => unsafe { (*p.as_ptr()).next = next },
            None => self.list.head = next,
        }
        match next {
            // SAFETY: `next` is a live neighbor node of the list (invariant 2).
            Some(n) => unsafe { (*n.as_ptr()).prev = prev },
            None => self.list.tail = prev,
        }

        self.list.len -= 1;
        self.cur = next.or(prev);
        Some(element)
    }

    pub fn insert_after(&mut self, element: T) {
        match self.cur {
            None => self.insert_into_empty(element),
            Some(cur) => {
                // SAFETY: `cur` is a live node of the list (invariant 3), and its
                // `next` (if any) is a live node too (invariant 2). We hold
                // exclusive access to the list via `&mut`. The new node is
                // linked in so that invariant 2 is maintained.
                unsafe {
                    let next = (*cur.as_ptr()).next;
                    let node = Node::alloc(element, Some(cur), next);
                    (*cur.as_ptr()).next = Some(node);
                    match next {
                        Some(n) => (*n.as_ptr()).prev = Some(node),
                        None => self.list.tail = Some(node),
                    }
                }
                self.list.len += 1;
            }
        }
    }

    pub fn insert_before(&mut self, element: T) {
        match self.cur {
            None => self.insert_into_empty(element),
            Some(cur) => {
                // SAFETY: `cur` is a live node of the list (invariant 3), and its
                // `prev` (if any) is a live node too (invariant 2). We hold
                // exclusive access to the list via `&mut`. The new node is
                // linked in so that invariant 2 is maintained.
                unsafe {
                    let prev = (*cur.as_ptr()).prev;
                    let node = Node::alloc(element, prev, Some(cur));
                    (*cur.as_ptr()).prev = Some(node);
                    match prev {
                        Some(p) => (*p.as_ptr()).next = Some(node),
                        None => self.list.head = Some(node),
                    }
                }
                self.list.len += 1;
            }
        }
    }

    /// Insert into an empty list. By invariant 3, `cur == None` implies
    /// the list is empty. The cursor is moved onto the new sole element.
    fn insert_into_empty(&mut self, element: T) {
        debug_assert!(self.list.is_empty());
        let node = Node::alloc(element, None, None);
        self.list.head = Some(node);
        self.list.tail = Some(node);
        self.list.len = 1;
        self.cur = Some(node);
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: the list is borrowed immutably for `'a` (invariant 4), so the
        // node is alive and not mutated for `'a`; handing out `&'a T` is sound.
        let node = unsafe { &*node.as_ptr() };
        self.next = node.next;
        Some(&node.element)
    }
}
