// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

/// A link to a node. `None` means "no node".
type Link<T> = Option<NonNull<Node<T>>>;

/// A single heap-allocated node of the list.
///
/// Nodes are always allocated via `Box` and converted into a raw `NonNull`
/// pointer. They are freed exactly once, via `Box::from_raw`, when they are
/// unlinked from the list.
struct Node<T> {
    element: T,
    prev: Link<T>,
    next: Link<T>,
}

/// A doubly linked list.
///
/// # Safety invariants
///
/// The following invariants are upheld by every (safe) public method and are
/// relied upon by all `unsafe` code in this module:
///
/// 1. `head.is_none() == tail.is_none() == (len == 0)`.
/// 2. Every node reachable from `head` (following `next`) was allocated with
///    `Box` and is exclusively owned by this list. No node is shared between
///    lists, and every node is freed exactly once.
/// 3. The links are consistent: for every node `n` in the list,
///    - if `n.next == Some(m)` then `m.prev == Some(n)`, otherwise `tail == Some(n)`;
///    - if `n.prev == Some(m)` then `m.next == Some(n)`, otherwise `head == Some(n)`.
/// 4. `len` equals the number of nodes reachable from `head`.
pub struct LinkedList<T> {
    head: Link<T>,
    tail: Link<T>,
    len: usize,
    /// Signals ownership of `T` values (for drop check) and keeps the list
    /// covariant over `T`.
    marker: PhantomData<Box<Node<T>>>,
}

/// A cursor that points at an element of the list and can mutate the list.
///
/// # Safety invariants
///
/// - `current` is `None` if and only if the list is empty.
/// - If `current` is `Some(node)`, then `node` is a node of `*list`.
///
/// The cursor holds an exclusive borrow of the list, so nothing else can
/// observe or mutate the list while the cursor exists.
pub struct Cursor<'a, T> {
    current: Link<T>,
    list: &'a mut LinkedList<T>,
}

/// An iterator over shared references to the elements of a list, from front to back.
///
/// # Safety invariants
///
/// `next`, if `Some`, points to a node of a list that is borrowed immutably for
/// `'a`. Therefore that node (and every node after it) remains valid and
/// unmodified for `'a`.
pub struct Iter<'a, T> {
    next: Link<T>,
    marker: PhantomData<&'a Node<T>>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        Cursor {
            current: self.head,
            list: self,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        Cursor {
            current: self.tail,
            list: self,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.head,
            marker: PhantomData,
        }
    }

    /// Allocates a new node holding `element` and links it in between `prev`
    /// and `next`. Returns a pointer to the new node.
    ///
    /// # Safety
    ///
    /// `prev` and `next` must be adjacent positions in *this* list:
    /// - if `prev == Some(p)`, then `p` is a node of this list and `p.next == next`;
    /// - if `prev == None`, then `next == self.head`;
    /// - if `next == Some(n)`, then `n` is a node of this list and `n.prev == prev`;
    /// - if `next == None`, then `prev == self.tail`.
    ///
    /// No references to the `prev`/`next` nodes may be alive during the call.
    unsafe fn link_between(&mut self, prev: Link<T>, next: Link<T>, element: T) -> NonNull<Node<T>> {
        let node = NonNull::from(Box::leak(Box::new(Node {
            element,
            prev,
            next,
        })));

        match prev {
            // SAFETY: by the caller's contract `p` is a valid node of this list,
            // we have exclusive access to the list (`&mut self`) and no
            // references to `p` are alive.
            Some(p) => unsafe { (*p.as_ptr()).next = Some(node) },
            None => self.head = Some(node),
        }
        match next {
            // SAFETY: same reasoning as for `prev` above.
            Some(n) => unsafe { (*n.as_ptr()).prev = Some(node) },
            None => self.tail = Some(node),
        }
        self.len += 1;
        node
    }

    /// Unlinks `node` from this list, frees it and returns its element.
    ///
    /// # Safety
    ///
    /// `node` must be a node of *this* list, and no references to it (or to
    /// its neighbours) may be alive during the call. After the call, `node`
    /// is dangling and must not be used again.
    unsafe fn unlink(&mut self, node: NonNull<Node<T>>) -> T {
        // SAFETY: `node` was allocated via `Box` and is owned by this list
        // (invariant 2 and caller contract). We reclaim ownership here; it is
        // removed from the list below, so it can't be freed twice.
        let boxed = unsafe { Box::from_raw(node.as_ptr()) };

        match boxed.prev {
            // SAFETY: by invariant 3, `p` is a valid node of this list and we
            // have exclusive access via `&mut self`.
            Some(p) => unsafe { (*p.as_ptr()).next = boxed.next },
            None => self.head = boxed.next,
        }
        match boxed.next {
            // SAFETY: by invariant 3, `n` is a valid node of this list and we
            // have exclusive access via `&mut self`.
            Some(n) => unsafe { (*n.as_ptr()).prev = boxed.prev },
            None => self.tail = boxed.prev,
        }
        self.len -= 1;
        boxed.element
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: by the cursor invariant, `node` is a valid node of the list,
        // which the cursor borrows exclusively. The returned reference borrows
        // `self` mutably, so the list cannot be modified (and the node cannot
        // be freed) while the reference is alive.
        self.current
            .map(|node| unsafe { &mut (*node.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let node = self.current?;
        // SAFETY: `node` is a valid node of the list (cursor invariant) and
        // we only read a `Copy` field through a short-lived shared reference.
        let next = unsafe { node.as_ref().next }?;
        self.current = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let node = self.current?;
        // SAFETY: `node` is a valid node of the list (cursor invariant) and
        // we only read a `Copy` field through a short-lived shared reference.
        let prev = unsafe { node.as_ref().prev }?;
        self.current = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;
        // SAFETY: `node` is a valid node of the list (cursor invariant); we
        // only copy its link fields.
        let (prev, next) = unsafe {
            let n = node.as_ref();
            (n.prev, n.next)
        };
        // If the list becomes empty, both are `None`, upholding the cursor
        // invariant. Otherwise the new position is a remaining node.
        self.current = next.or(prev);
        // SAFETY: `node` belongs to `self.list` (cursor invariant). No
        // references to it are alive: `peek_mut` references borrow `self`
        // mutably, so they can't coexist with this call. The cursor no longer
        // points to `node`, so it won't be used after being freed.
        Some(unsafe { self.list.unlink(node) })
    }

    pub fn insert_after(&mut self, element: T) {
        match self.current {
            None => {
                // Cursor invariant: the list is empty, so `None, None` are
                // adjacent positions (head == tail == None).
                // SAFETY: see above; no node references exist.
                let node = unsafe { self.list.link_between(None, None, element) };
                // Keep the invariant: list is non-empty now, so point at a node.
                self.current = Some(node);
            }
            Some(cur) => {
                // SAFETY: `cur` is a valid node of the list (cursor invariant).
                let next = unsafe { cur.as_ref().next };
                // SAFETY: `cur` and `cur.next` are adjacent in this list by
                // invariant 3; no references to nodes are alive.
                unsafe {
                    self.list.link_between(Some(cur), next, element);
                }
            }
        }
    }

    pub fn insert_before(&mut self, element: T) {
        match self.current {
            None => {
                // Cursor invariant: the list is empty, so `None, None` are
                // adjacent positions (head == tail == None).
                // SAFETY: see above; no node references exist.
                let node = unsafe { self.list.link_between(None, None, element) };
                // Keep the invariant: list is non-empty now, so point at a node.
                self.current = Some(node);
            }
            Some(cur) => {
                // SAFETY: `cur` is a valid node of the list (cursor invariant).
                let prev = unsafe { cur.as_ref().prev };
                // SAFETY: `cur.prev` and `cur` are adjacent in this list by
                // invariant 3; no references to nodes are alive.
                unsafe {
                    self.list.link_between(prev, Some(cur), element);
                }
            }
        }
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: by the `Iter` invariant, the list is immutably borrowed for
        // `'a`, so `node` stays valid and is not mutated for `'a`. Handing out
        // a shared reference with lifetime `'a` is therefore sound.
        let node_ref: &'a Node<T> = unsafe { &*node.as_ptr() };
        self.next = node_ref.next;
        Some(&node_ref.element)
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Unlink nodes one by one from the front. The list stays consistent
        // after every step, so even if dropping an element panics, no
        // dangling pointers remain in the list.
        while let Some(node) = self.head {
            // SAFETY: `node` is the head of this list (invariants 1-3), and no
            // references to any node are alive since we have `&mut self`.
            let element = unsafe { self.unlink(node) };
            drop(element);
        }
    }
}

// SAFETY: `LinkedList<T>` owns its `T` values just like `Box<T>` / `Vec<T>`
// do. The raw pointers are never shared with anything outside the list, so
// sending the list to another thread is sound if `T` can be sent.
unsafe impl<T: Send> Send for LinkedList<T> {}

// SAFETY: through `&LinkedList<T>` one can only obtain `&T` (via `iter`), so
// sharing the list across threads is sound if `T` can be shared.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: a `Cursor` is semantically a `&mut LinkedList<T>` plus a position.
// `&mut LinkedList<T>` is `Send` when `LinkedList<T>: Send`, i.e. `T: Send`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}

// SAFETY: through `&Cursor<T>` no access to the elements is possible at all;
// mirroring `&mut LinkedList<T>`, it is `Sync` when `T: Sync`.
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: an `Iter` is semantically a `&'a LinkedList<T>` handing out `&'a T`,
// which is `Send` when `T: Sync`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}

// SAFETY: same reasoning as above; `&Iter<T>` gives no more access than `&T`.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}
