// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

// Safety-critical invariants of `LinkedList<T>`:
//
// 1. Every node reachable from `head` (following `next`) or from `tail`
//    (following `prev`) was allocated via `Box::into_raw` and is owned
//    exclusively by this list. It is freed exactly once, via `Box::from_raw`,
//    when it is removed from the list.
// 2. `head` is `None` iff `tail` is `None` iff `len == 0`.
// 3. For every node `n`: `n.next == Some(m)` iff `m.prev == Some(n)`.
//    `head.prev` and `tail.next` are `None`.
// 4. `len` equals the number of nodes in the list.
//
// Shared/mutable access to nodes follows the borrow of the owning list:
// `Iter` borrows the list immutably and `Cursor` borrows it mutably,
// so no aliasing violations can occur through the safe API.

type Link<T> = Option<NonNull<Node<T>>>;

struct Node<T> {
    elem: T,
    prev: Link<T>,
    next: Link<T>,
}

pub struct LinkedList<T> {
    head: Link<T>,
    tail: Link<T>,
    len: usize,
    // We logically own boxed nodes containing `T` (important for drop check).
    _marker: PhantomData<Box<Node<T>>>,
}

pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    // Invariant: `None` only if the list is empty; otherwise points to a node
    // of `list`.
    cur: Link<T>,
}

pub struct Iter<'a, T> {
    next: Link<T>,
    _marker: PhantomData<&'a Node<T>>,
}

// SAFETY: LinkedList owns its elements just like a `Box<T>`/`Vec<T>` does.
// There is no shared interior state, so sending it is safe if `T: Send`.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: `&LinkedList<T>` only gives out `&T`, so sharing is safe if `T: Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: A cursor behaves like `&mut LinkedList<T>`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: An iterator behaves like `&LinkedList<T>`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let cur = self.head;
        Cursor { list: self, cur }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let cur = self.tail;
        Cursor { list: self, cur }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.head,
            _marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cursor = self.cursor_front();
        while cursor.take().is_some() {}
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `cur` points to a live node owned by the list (invariant 1).
        // The cursor holds the unique mutable borrow of the list, and the
        // returned reference is tied to `&mut self`, so no aliasing occurs.
        self.cur.map(|node| unsafe { &mut (*node.as_ptr()).elem })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let cur = self.cur?;
        // SAFETY: `cur` points to a live node of the list (invariant 1).
        let next = unsafe { (*cur.as_ptr()).next }?;
        self.cur = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let cur = self.cur?;
        // SAFETY: `cur` points to a live node of the list (invariant 1).
        let prev = unsafe { (*cur.as_ptr()).prev }?;
        self.cur = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let cur = self.cur?;
        // SAFETY: `cur` was created by `Box::into_raw` and is owned by the
        // list (invariant 1). We unlink it below, so it is no longer reachable
        // from the list and will not be freed again.
        let node = unsafe { Box::from_raw(cur.as_ptr()) };

        // SAFETY: neighbours are live nodes of the list (invariants 1 and 3).
        unsafe {
            match node.prev {
                Some(p) => (*p.as_ptr()).next = node.next,
                None => self.list.head = node.next,
            }
            match node.next {
                Some(n) => (*n.as_ptr()).prev = node.prev,
                None => self.list.tail = node.prev,
            }
        }

        self.list.len -= 1;
        self.cur = node.next.or(node.prev);
        Some(node.elem)
    }

    pub fn insert_after(&mut self, element: T) {
        let new = NonNull::from(Box::leak(Box::new(Node {
            elem: element,
            prev: self.cur,
            next: None,
        })));

        match self.cur {
            None => {
                // Empty list (cursor invariant).
                self.list.head = Some(new);
                self.list.tail = Some(new);
                self.cur = Some(new);
            }
            Some(cur) => {
                // SAFETY: `cur`, its successor and `new` are live nodes; we
                // relink them to preserve invariant 3.
                unsafe {
                    let next = (*cur.as_ptr()).next;
                    (*new.as_ptr()).next = next;
                    match next {
                        Some(n) => (*n.as_ptr()).prev = Some(new),
                        None => self.list.tail = Some(new),
                    }
                    (*cur.as_ptr()).next = Some(new);
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new = NonNull::from(Box::leak(Box::new(Node {
            elem: element,
            prev: None,
            next: self.cur,
        })));

        match self.cur {
            None => {
                // Empty list (cursor invariant).
                self.list.head = Some(new);
                self.list.tail = Some(new);
                self.cur = Some(new);
            }
            Some(cur) => {
                // SAFETY: `cur`, its predecessor and `new` are live nodes; we
                // relink them to preserve invariant 3.
                unsafe {
                    let prev = (*cur.as_ptr()).prev;
                    (*new.as_ptr()).prev = prev;
                    match prev {
                        Some(p) => (*p.as_ptr()).next = Some(new),
                        None => self.list.head = Some(new),
                    }
                    (*cur.as_ptr()).prev = Some(new);
                }
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: the iterator holds a shared borrow of the list for 'a, so
        // the node is alive and not mutated for the duration of 'a.
        unsafe {
            let node = &*node.as_ptr();
            self.next = node.next;
            Some(&node.elem)
        }
    }
}
