// Every unsafe operation needs its own `unsafe` block (and justification),
// even inside of `unsafe fn`s.
#![warn(unsafe_op_in_unsafe_fn)]

// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

// Safety-critical invariants
// ==========================
//
// A `LinkedList` owns a chain of heap allocated `Node`s. Every node is created
// by `Node::alloc` (as a leaked `Box`) and freed exactly once, by turning it
// back into a `Box` in `LinkedList::unlink`.
//
// A position in the list is a `Link`: `Some(node)` is that node and `None` is
// a "ghost" position that conceptually sits between the back and the front, as
// if the list were circular. The ghost's `next` link is `head` and its `prev`
// link is `tail`. This gets rid of most special cases for the ends of the list.
//
// These invariants hold at the start and at the end of every function in this
// file. They may only be broken temporarily, while one of them is running.
//
// 1. Structure: Starting at the ghost, following the `next` links visits
//    exactly `len` distinct, live nodes and then arrives back at the ghost.
//    The `prev` links mirror the `next` links: `b` is the `next` of `a` if and
//    only if `a` is the `prev` of `b`. (So `head` and `tail` are `None` if and
//    only if the list is empty.)
// 2. Ownership: Each node belongs to exactly one list. Pointers to it only
//    exist inside of that list and inside of `Iter`s and `Cursor`s, which
//    borrow the list immutably or mutably respectively. So while an `Iter`
//    exists, the nodes can be neither modified nor freed, and while a
//    `Cursor` exists, nothing but the cursor can access them.
// 3. Aliasing: References into nodes are only handed out for the `element`
//    and their lifetime is bound to a borrow of the list or of a cursor. The
//    `prev` and `next` links are only accessed by the code in this file and
//    only modified through a `&mut LinkedList`.
//
// A `Cursor` additionally guarantees that its `current` position is the ghost
// (`None`) if and only if the list is empty; otherwise it's a node of the list.
//
// An `Iter` guarantees that `next` is `None` or a node of the list it borrows,
// and that `remaining` is the number of nodes from `next` to the back.

/// A position in the list, see the explanation above.
type Link<T> = Option<NonNull<Node<T>>>;

struct Node<T> {
    element: T,
    prev: Link<T>,
    next: Link<T>,
}

impl<T> Node<T> {
    /// Moves a new node to the heap and returns a pointer to it.
    ///
    /// The caller becomes the owner of the allocation. It has to be released
    /// with `Box::from_raw` eventually, otherwise it is leaked.
    fn alloc(element: T, prev: Link<T>, next: Link<T>) -> NonNull<Self> {
        let node = Box::new(Node {
            element,
            prev,
            next,
        });
        NonNull::from(Box::leak(node))
    }
}

pub struct LinkedList<T> {
    head: Link<T>,
    tail: Link<T>,
    len: usize,
    // Tells the drop checker that the list owns (and drops) `T`s.
    // Together with `NonNull` being covariant, this makes `LinkedList<T>`
    // covariant over `T`, just like `Box<T>` or `Vec<T>`. That's sound,
    // because the list can only be modified through a `&mut LinkedList<T>`,
    // which is invariant over `T`.
    _owns: PhantomData<Box<Node<T>>>,
}

pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Link<T>,
}

pub struct Iter<'a, T> {
    next: Link<T>,
    remaining: usize,
    // `Iter` behaves like a `&'a T`, which also makes it covariant.
    _borrow: PhantomData<&'a T>,
}

// SAFETY: A `LinkedList<T>` exclusively owns its elements, just like a `Vec<T>`
// does, and it doesn't share any state with other values (invariant 2).
// Sending it to another thread just moves the elements there, which is fine
// if `T: Send`.
unsafe impl<T: Send> Send for LinkedList<T> {}

// SAFETY: A `&LinkedList<T>` only allows reading the list and obtaining `&T`s,
// there is no interior mutability. So sharing a list between threads is fine
// if sharing its elements is, i.e. if `T: Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: An `Iter<'a, T>` acts like a `&'a LinkedList<T>`, which is `Send`
// if `LinkedList<T>: Sync`, i.e. if `T: Sync`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}

// SAFETY: An `Iter<'a, T>` acts like a `&'a LinkedList<T>`, which is `Sync`
// if `LinkedList<T>: Sync`, i.e. if `T: Sync`.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

// SAFETY: A `Cursor<'a, T>` acts like a `&'a mut LinkedList<T>`, which is
// `Send` if `LinkedList<T>: Send`, i.e. if `T: Send`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}

// SAFETY: A `Cursor<'a, T>` acts like a `&'a mut LinkedList<T>`, which is
// `Sync` if `LinkedList<T>: Sync`, i.e. if `T: Sync`. (A `&Cursor` doesn't
// even allow any access to the list.)
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            _owns: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    // Not expensive here: the length is updated by every insertion and removal.
    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        Cursor {
            current: self.head,
            list: self,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        Cursor {
            current: self.tail,
            list: self,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.head,
            remaining: self.len,
            _borrow: PhantomData,
        }
    }
}

// Low level building blocks for the cursor.
impl<T> LinkedList<T> {
    /// Returns the `next` link of the position `pos`. For the ghost position
    /// (`None`) that's `head`.
    ///
    /// # Safety
    /// `pos` must be `None` or point to a live node owned by `self`.
    unsafe fn next_link(&mut self, pos: Link<T>) -> &mut Link<T> {
        match pos {
            // SAFETY: The caller guarantees that `node` is a live node of this
            // list. We have exclusive access to the list and thereby to the
            // node, and no other reference to its links exists (invariant 3),
            // so it may be borrowed mutably for as long as `self` is.
            Some(node) => unsafe { &mut (*node.as_ptr()).next },
            None => &mut self.head,
        }
    }

    /// Returns the `prev` link of the position `pos`. For the ghost position
    /// (`None`) that's `tail`.
    ///
    /// # Safety
    /// `pos` must be `None` or point to a live node owned by `self`.
    unsafe fn prev_link(&mut self, pos: Link<T>) -> &mut Link<T> {
        match pos {
            // SAFETY: Same as in `next_link`.
            Some(node) => unsafe { &mut (*node.as_ptr()).prev },
            None => &mut self.tail,
        }
    }

    /// Links a new node holding `element` in between the positions `prev` and
    /// `next` and returns a pointer to it.
    ///
    /// # Safety
    /// `prev` and `next` must be adjacent positions of `self`: each of them is
    /// either `None` (the ghost) or a live node owned by `self`, and `next` is
    /// the successor of `prev` (thus `prev` is the predecessor of `next`).
    unsafe fn insert_between(
        &mut self,
        prev: Link<T>,
        next: Link<T>,
        element: T,
    ) -> NonNull<Node<T>> {
        let node = Node::alloc(element, prev, next);
        // SAFETY: The caller guarantees that `prev` and `next` are positions of
        // `self`. As they are adjacent, pointing their links at `node` (whose
        // own links already point back at them) splices it into the chain
        // while keeping all links mirrored (invariant 1). From now on, the
        // list owns `node` (invariant 2).
        unsafe {
            *self.next_link(prev) = Some(node);
            *self.prev_link(next) = Some(node);
        }
        self.len += 1;
        node
    }

    /// Unlinks `node` from the list and hands ownership of it to the caller.
    ///
    /// # Safety
    /// `node` must point to a live node owned by `self`. Afterwards it isn't
    /// part of the list anymore, so the pointer must not be used to access
    /// the list again.
    unsafe fn unlink(&mut self, node: NonNull<Node<T>>) -> Box<Node<T>> {
        // SAFETY: The caller guarantees that `node` is a live node of `self`.
        // Its links are only copied, no reference is created.
        let (prev, next) = unsafe { ((*node.as_ptr()).prev, (*node.as_ptr()).next) };
        // SAFETY: The neighbors of a node of `self` are positions of `self`
        // (invariant 1). Linking them to each other removes `node` from the
        // chain in both directions and keeps the links mirrored.
        unsafe {
            *self.next_link(prev) = next;
            *self.prev_link(next) = prev;
        }
        self.len -= 1;
        // SAFETY: Every node was allocated as a `Box` by `Node::alloc`. `node`
        // isn't reachable from the list anymore, so the list gives up its
        // ownership here, which can only happen once per node.
        unsafe { Box::from_raw(node.as_ptr()) }
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        let node = self.current?;
        // SAFETY: `node` is a live node of the list (cursor invariant), to
        // which the cursor has exclusive access. The returned reference
        // borrows the cursor mutably, so as long as it exists the node can
        // neither be freed (`take`) nor accessed in any other way.
        Some(unsafe { &mut (*node.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    ///
    /// If there is no next element, the cursor stays where it is and `None`
    /// is returned.
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: `current` is a live node of the list (cursor invariant).
        // Its link is only copied, no reference is created.
        let next = unsafe { (*current.as_ptr()).next }?;
        // `next` is a node of the list as well (invariant 1).
        self.current = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    ///
    /// If there is no previous element, the cursor stays where it is and
    /// `None` is returned.
    pub fn prev(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: `current` is a live node of the list (cursor invariant).
        // Its link is only copied, no reference is created.
        let prev = unsafe { (*current.as_ptr()).prev }?;
        // `prev` is a node of the list as well (invariant 1).
        self.current = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let current = self.current?;
        // SAFETY: `current` is a live node of the list (cursor invariant).
        // It's replaced as the cursor position right below, so the pointer
        // isn't used to access the list afterwards.
        let node = unsafe { self.list.unlink(current) };
        let Node {
            element,
            prev,
            next,
        } = *node;
        // The former neighbors are still nodes of the list. If there are none,
        // the list is empty now and the cursor moves to the ghost position.
        self.current = next.or(prev);
        Some(element)
    }

    pub fn insert_after(&mut self, element: T) {
        let prev = self.current;
        // SAFETY: `prev` is a live node of the list or the ghost position
        // (cursor invariant).
        let next = unsafe { *self.list.next_link(prev) };
        // SAFETY: `next` was just read as the successor of `prev`, so they
        // are adjacent positions of the list.
        let new = unsafe { self.list.insert_between(prev, next, element) };
        if self.current.is_none() {
            // The list was empty. Now that it isn't, the cursor has to be on
            // an element: the only one there is.
            self.current = Some(new);
        }
    }

    pub fn insert_before(&mut self, element: T) {
        let next = self.current;
        // SAFETY: `next` is a live node of the list or the ghost position
        // (cursor invariant).
        let prev = unsafe { *self.list.prev_link(next) };
        // SAFETY: `prev` was just read as the predecessor of `next`, so they
        // are adjacent positions of the list.
        let new = unsafe { self.list.insert_between(prev, next, element) };
        if self.current.is_none() {
            // The list was empty. Now that it isn't, the cursor has to be on
            // an element: the only one there is.
            self.current = Some(new);
        }
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: `node` is a live node of the list that this iterator borrows
        // immutably for `'a` (iterator invariant). During `'a`, the list can be
        // neither modified nor dropped (invariant 2), so the node stays alive
        // and unchanged and may be shared for all of `'a`.
        let node = unsafe { &*node.as_ptr() };
        self.next = node.next;
        self.remaining -= 1;
        Some(&node.element)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Remove the elements one by one, which drops them and frees their
        // nodes. Doing this iteratively (instead of recursively) means even
        // huge lists can't overflow the stack. Should the destructor of an
        // element panic, the remaining nodes are leaked, which is safe.
        let mut cursor = self.cursor_front();
        while cursor.take().is_some() {}
    }
}
