#include "queen_attack.h"

#include <cstdlib>
#include <stdexcept>

namespace queen_attack {

namespace {
bool on_board(const std::pair<int, int>& p) {
    return p.first >= 0 && p.first < 8 && p.second >= 0 && p.second < 8;
}
}  // namespace

chess_board::chess_board(std::pair<int, int> white, std::pair<int, int> black)
    : white_(white), black_(black) {
    if (!on_board(white_) || !on_board(black_)) {
        throw std::domain_error("Queen position must be on the board");
    }
    if (white_ == black_) {
        throw std::domain_error("Queens cannot occupy the same position");
    }
}

bool chess_board::can_attack() const {
    int dr = white_.first - black_.first;
    int dc = white_.second - black_.second;
    return dr == 0 || dc == 0 || std::abs(dr) == std::abs(dc);
}

chess_board::operator std::string() const {
    std::string result;
    for (int row = 0; row < 8; ++row) {
        for (int col = 0; col < 8; ++col) {
            if (col > 0) result += ' ';
            auto pos = std::make_pair(row, col);
            if (pos == white_) {
                result += 'W';
            } else if (pos == black_) {
                result += 'B';
            } else {
                result += '_';
            }
        }
        result += '\n';
    }
    return result;
}

}  // namespace queen_attack
