The stub needs a full implementation. The approach:

1. **Validate the frame.** The question must start with `What is` and end with `?`. Anything else, such as "Who is the President…", is rejected.
2. **Tokenize** the remaining text into words.
3. **Parse strictly as `number (operator number)*`**:
   - The first token must be a number. This rejects prefix notation and an empty "What is?".
   - Each operator must be `plus` or `minus`, or the two-word forms `multiplied by` and `divided by`. Any other word, like `cubed`, is rejected. So is a number where an operator is expected, which covers postfix notation and two numbers in a row.
   - Each operator must be followed by a number. This rejects "1 plus plus 2" and "1 plus?".
4. **Evaluate left to right** as you parse, ignoring normal operator precedence.
5. **Reject division by zero** so the function returns `false` instead of panicking.

wordy.go
```go
package wordy

import (
	"strconv"
	"strings"
)

// Answer parses and evaluates a simple math word problem such as
// "What is 3 plus 2 multiplied by 3?". Operations are evaluated strictly
// from left to right, ignoring the usual order of operations.
// The boolean result reports whether the question could be parsed and
// evaluated successfully.
func Answer(question string) (int, bool) {
	if !strings.HasSuffix(question, "?") {
		return 0, false
	}

	words := strings.Fields(strings.TrimSuffix(question, "?"))
	if len(words) < 3 || words[0] != "What" || words[1] != "is" {
		return 0, false
	}
	words = words[2:]

	// The expression must start with a number.
	result, err := strconv.Atoi(words[0])
	if err != nil {
		return 0, false
	}

	// Then it must consist of (operator, number) pairs.
	for i := 1; i < len(words); {
		op := words[i]
		i++

		switch op {
		case "plus", "minus":
			// single-word operators
		case "multiplied", "divided":
			// two-word operators: "multiplied by", "divided by"
			if i >= len(words) || words[i] != "by" {
				return 0, false
			}
			i++
		default:
			// unsupported operation or invalid syntax
			return 0, false
		}

		// Every operator must be followed by a number.
		if i >= len(words) {
			return 0, false
		}
		operand, err := strconv.Atoi(words[i])
		if err != nil {
			return 0, false
		}
		i++

		switch op {
		case "plus":
			result += operand
		case "minus":
			result -= operand
		case "multiplied":
			result *= operand
		case "divided":
			if operand == 0 {
				return 0, false
			}
			result /= operand
		}
	}

	return result, true
}
