// Answer parses and evaluates a simple math word problem.
// It returns the result and true on success, or 0 and false if the
// question is invalid or unsupported.
func Answer(question string) (int, bool) {
	const prefix = "What is"
	const suffix = "?"

	if !strings.HasPrefix(question, prefix) || !strings.HasSuffix(question, suffix) {
		return 0, false
	}

	body := strings.TrimSuffix(strings.TrimPrefix(question, prefix), suffix)
	fields := strings.Fields(body)
	if len(fields) == 0 {
		return 0, false
	}

	// Combine two-word operators into single tokens.
	tokens := make([]string, 0, len(fields))
	for i := 0; i < len(fields); i++ {
		f := fields[i]
		if (f == "multiplied" || f == "divided") && i+1 < len(fields) && fields[i+1] == "by" {
			tokens = append(tokens, f+" by")
			i++
			continue
		}
		tokens = append(tokens, f)
	}

	result, err := strconv.Atoi(tokens[0])
	if err != nil {
		return 0, false
	}

	for i := 1; i < len(tokens); i += 2 {
		op := tokens[i]
		if i+1 >= len(tokens) {
			// Operator (or unknown word) without a following operand.
			return 0, false
		}
		n, err := strconv.Atoi(tokens[i+1])
		if err != nil {
			return 0, false
		}

		switch op {
		case "plus":
			result += n
		case "minus":
			result -= n
		case "multiplied by":
			result *= n
		case "divided by":
			if n == 0 {
				return 0, false
			}
			result /= n
		default:
			return 0, false
		}
	}

	return result, true
}
