- **`Verse(n)`** returns one verse ending with a newline. It returns an error if `n` is outside 0–99.
  - It handles the special verses: 0 (go to the store), 1 ("Take it down", "no more"), and 2 (singular "1 bottle").
- **`Verses(start, stop)`** joins verses from `start` down to `stop`. Each verse is followed by a blank line. It returns an error if either bound is out of range or `start < stop`.
- **`Song()`** returns the full song, verses 99 down to 0.

beer_song.go
```go
package beer

import (
	"errors"
	"fmt"
	"strings"
)

// Song returns the full lyrics of the song, from 99 down to 0.
func Song() string {
	s, _ := Verses(99, 0)
	return s
}

// Verses returns the verses from start down to stop (inclusive),
// each followed by a blank line.
func Verses(start, stop int) (string, error) {
	if start < 0 || start > 99 || stop < 0 || stop > 99 {
		return "", errors.New("verse numbers must be between 0 and 99")
	}
	if start < stop {
		return "", errors.New("start must be greater than or equal to stop")
	}
	var b strings.Builder
	for n := start; n >= stop; n-- {
		v, err := Verse(n)
		if err != nil {
			return "", err
		}
		b.WriteString(v)
		b.WriteString("\n")
	}
	return b.String(), nil
}

// Verse returns a single verse for n bottles.
func Verse(n int) (string, error) {
	switch {
	case n < 0 || n > 99:
		return "", fmt.Errorf("invalid verse number: %d", n)
	case n == 0:
		return "No more bottles of beer on the wall, no more bottles of beer.\n" +
			"Go to the store and buy some more, 99 bottles of beer on the wall.\n", nil
	case n == 1:
		return "1 bottle of beer on the wall, 1 bottle of beer.\n" +
			"Take it down and pass it around, no more bottles of beer on the wall.\n", nil
	case n == 2:
		return "2 bottles of beer on the wall, 2 bottles of beer.\n" +
