beer_song.go
```go
// Package beer recites the lyrics to "99 Bottles of Beer on the Wall".
package beer

import (
	"fmt"
	"strings"
)

// maxBottles is the number of bottles the song starts with.
const maxBottles = 99

// Song returns the lyrics of the entire song.
func Song() string {
	return verses(maxBottles, 0)
}

// Verses returns the verses from start down to stop (inclusive),
// each verse followed by a blank line.
func Verses(start, stop int) (string, error) {
	switch {
	case !valid(start):
		return "", fmt.Errorf("invalid start verse %d: must be between 0 and %d", start, maxBottles)
	case !valid(stop):
		return "", fmt.Errorf("invalid stop verse %d: must be between 0 and %d", stop, maxBottles)
	case start < stop:
		return "", fmt.Errorf("start verse %d is less than stop verse %d", start, stop)
	}
	return verses(start, stop), nil
}

// Verse returns the single verse sung with n bottles on the wall.
func Verse(n int) (string, error) {
	if !valid(n) {
		return "", fmt.Errorf("invalid verse %d: must be between 0 and %d", n, maxBottles)
	}
	return verse(n), nil
}

// verses builds the verses from start down to stop without validation.
func verses(start, stop int) string {
	var b strings.Builder
	for n := start; n >= stop; n-- {
		b.WriteString(verse(n))
		b.WriteString("\n")
	}
	return b.String()
}

// verse builds the verse for n bottles without validation.
func verse(n int) string {
	return fmt.Sprintf(
		"%s of beer on the wall, %s of beer.\n%s, %s of beer on the wall.\n",
		capitalize(bottles(n)), bottles(n), action(n), bottles(remaining(n)),
	)
}

// valid reports whether n is a verse number that exists in the song.
func valid(n int) bool {
	return 0 <= n && n <= maxBottles
}

// bottles describes a quantity of bottles, e.g. "2 bottles", "1 bottle".
func bottles(n int) string {
	switch n {
	case 0:
		return "no more bottles"
	case 1:
		return "1 bottle"
	default:
		return fmt.Sprintf("%d bottles", n)
	}
}

// action describes what happens to the bottles in verse n.
func action(n int) string {
	switch n {
	case 0:
		return "Go to the store and buy some more"
	case 1:
		return "Take it down and pass it around"
	default:
		return "Take one down and pass it around"
	}
}

// remaining returns how many bottles are on the wall after verse n.
func remaining(n int) int {
	if n == 0 {
		return maxBottles
	}
	return n - 1
}

// capitalize upper-cases the first letter of s.
func capitalize(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}
