class EmptyListException(Exception):
    """Exception raised when an operation requires a non-empty linked list.

    message: explanation of the error.
    """

    def __init__(self, message="The list is empty."):
        self.message = message
        super().__init__(message)


class Node:
    """A single element (song) in a singly linked list."""

    def __init__(self, value, next_node=None):
        self._value = value
        self._next = next_node

    def value(self):
        """Return the data stored in this node."""
        return self._value

    def next(self):
        """Return the next node in the list (or None if this is the tail)."""
        return self._next


class LinkedList:
    """A LIFO stack implemented with a custom singly linked list.

    The most recently pushed value is always the head of the list.
    """

    def __init__(self, values=None):
        self._head = None
        self._length = 0
        if values is not None:
            for value in values:
                self.push(value)

    def __iter__(self):
        current = self._head
        while current is not None:
            yield current.value()
            current = current.next()

    def __len__(self):
        return self._length

    def __reversed__(self):
        return iter(self.reversed())

    def head(self):
        """Return the head node, raising EmptyListException if the list is empty."""
        if self._head is None:
            raise EmptyListException("The list is empty.")
        return self._head

    def push(self, value):
        """Add a new value to the front (head) of the list."""
        self._head = Node(value, self._head)
        self._length += 1

    def pop(self):
        """Remove the head node and return its value.

        Raises EmptyListException if the list is empty.
        """
        if self._head is None:
            raise EmptyListException("The list is empty.")
        node = self._head
        self._head = node.next()
        self._length -= 1
        return node.value()

    def reversed(self):
        """Return a new LinkedList with the elements in the opposite order."""
        # Iterating yields values head-first; pushing them onto a new list
        # places the original tail at the new head, reversing the order.
        return LinkedList(self)
```

