        return "PythagoreanTriplet{" + a + ", " + b + ", " + c + "}";
    }

    static class TripletListBuilder {

        private int sum = 0;
        private int maxFactor = 0;

        TripletListBuilder thatSumTo(int sum) {
            this.sum = sum;
            return this;
        }

        TripletListBuilder withFactorsLessThanOrEqualTo(int maxFactor) {
            this.maxFactor = maxFactor;
            return this;
        }

        List<PythagoreanTriplet> build() {
            List<PythagoreanTriplet> result = new ArrayList<>();
            long n = sum;
            long limit = maxFactor > 0 ? maxFactor : n;
            for (long a = 1; a < n / 3; a++) {
                long numerator = n * n - 2 * n * a;
                long denominator = 2 * (n - a);
                if (denominator <= 0 || numerator % denominator != 0) {
                    continue;
                }
                long b = numerator / denominator;
                long c = n - a - b;
                if (a < b && b < c && c <= limit) {
                    result.add(new PythagoreanTriplet((int) a, (int) b, (int) c));
                }
            }
            return result;
        }

    }

}
