//
// Palindrome Products exercise
//

const isPalindrome = (n) => {
  if (n < 0) return false;
  let reversed = 0;
  let m = n;
  while (m > 0) {
    reversed = reversed * 10 + (m % 10);
    m = Math.floor(m / 10);
  }
  return reversed === n;
};

export class Palindromes {
  constructor(minFactor, maxFactor) {
    this.minFactor = minFactor;
    this.maxFactor = maxFactor;
    this._smallest = undefined;
    this._largest = undefined;
  }

  static generate({ minFactor = 1, maxFactor } = {}) {
    return new Palindromes(minFactor, maxFactor);
  }

  _validate() {
    if (this.minFactor > this.maxFactor) {
      throw new Error('min must be <= max');
    }
  }

  get smallest() {
    this._validate();
    if (this._smallest !== undefined) return this._smallest;

    const min = this.minFactor;
    const max = this.maxFactor;
    let value = null;
    let factors = [];

    for (let i = min; i <= max; i++) {
      if (value !== null && i * i > value) break;
      for (let j = i; j <= max; j++) {
        const product = i * j;
        if (value !== null && product > value) break;
        if (isPalindrome(product)) {
          if (value === null || product < value) {
            value = product;
            factors = [[i, j]];
          } else if (product === value) {
            factors.push([i, j]);
          }
          // Any larger j only produces larger products
          break;
        }
      }
    }

    this._smallest = { value, factors };
    return this._smallest;
  }

  get largest() {
    this._validate();
    if (this._largest !== undefined) return this._largest;

    const min = this.minFactor;
    const max = this.maxFactor;
    let value = null;
    let factors = [];

    for (let i = max; i >= min; i--) {
      if (value !== null && i * max < value) break;
      for (let j = max; j >= i; j--) {
        const product = i * j;
        if (value !== null && product < value) break;
        if (isPalindrome(product)) {
          if (value === null || product > value) {
            value = product;
            factors = [[i, j]];
          } else if (product === value) {
            factors.push([i, j]);
          }
          // Any smaller j only produces smaller products
          break;
        }
      }
    }

    this._largest = { value, factors };
    return this._largest;
  }
}
