//
// Palindrome Products
//

const isPalindrome = (n) => {
  const s = String(n);
  let i = 0;
  let j = s.length - 1;
  while (i < j) {
    if (s[i] !== s[j]) return false;
    i++;
    j--;
  }
  return true;
};

const factorsOf = (value, min, max) => {
  const factors = [];
  for (let a = min; a <= max && a * a <= value; a++) {
    if (value % a === 0) {
      const b = value / a;
      if (b >= min && b <= max) {
        factors.push([a, b]);
      }
    }
  }
  return factors;
};

export class Palindromes {
  static generate({ maxFactor, minFactor = 1 } = {}) {
    const min = minFactor;
    const max = maxFactor;

    const validate = () => {
      if (min > max) {
        throw new Error('min must be <= max');
      }
    };

    let smallestCache;
    let largestCache;

    return {
      get smallest() {
        validate();
        if (smallestCache) return smallestCache;
        let best = null;
        for (let i = min; i <= max; i++) {
          if (best !== null && i * i > best) break;
          for (let j = i; j <= max; j++) {
            const p = i * j;
            if (best !== null && p >= best) break;
            if (isPalindrome(p)) {
              best = p;
              break;
            }
          }
        }
        smallestCache =
          best === null
            ? { value: null, factors: [] }
            : { value: best, factors: factorsOf(best, min, max) };
        return smallestCache;
      },

      get largest() {
        validate();
        if (largestCache) return largestCache;
        let best = null;
        for (let i = max; i >= min; i--) {
          if (best !== null && i * max < best) break;
          for (let j = max; j >= i; j--) {
            const p = i * j;
            if (best !== null && p <= best) break;
            if (isPalindrome(p)) {
              best = p;
              break;
            }
          }
        }
        largestCache =
          best === null
            ? { value: null, factors: [] }
            : { value: best, factors: factorsOf(best, min, max) };
        return largestCache;
      },
    };
  }
}
