    let smallest = null;
    for (let i = minFactor; i <= maxFactor; i++) {
      if (smallest !== null && i * i > smallest) break;
      for (let j = i; j <= maxFactor; j++) {
        const p = i * j;
        if (smallest !== null && p >= smallest) break;
        if (isPalindrome(p)) {
          smallest = p;
          break;
        }
      }
    }

    // Largest
    let largest = null;
    for (let i = maxFactor; i >= minFactor; i--) {
      if (largest !== null && i * maxFactor < largest) break;
      for (let j = maxFactor; j >= i; j--) {
        const p = i * j;
        if (largest !== null && p <= largest) break;
        if (isPalindrome(p)) {
          largest = p;
          break;
        }
      }
    }

    return {
      smallest: {
        value: smallest,
        factors: factorsOf(smallest, minFactor, maxFactor),
      },
      largest: {
        value: largest,
        factors: factorsOf(largest, minFactor, maxFactor),
      },
    };
  }
