#[derive(Debug)]
pub enum Error {
    InvalidTonic,
    InvalidInterval(char),
}

pub struct Scale {
    notes: Vec<String>,
}

const SHARPS: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];
const FLATS: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];
const FLAT_TONICS: [&str; 12] = [
    "F", "Bb", "Eb", "Ab", "Db", "Gb", "d", "g", "c", "f", "bb", "eb",
];

fn normalize(s: &str) -> String {
    let mut c = s.chars();
    match c.next() {
        Some(f) => f.to_ascii_uppercase().to_string() + &c.as_str().to_ascii_lowercase(),
        None => String::new(),
    }
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let table = if FLAT_TONICS.contains(&tonic) { &FLATS } else { &SHARPS };
        let name = normalize(tonic);
        let mut idx = table
            .iter()
            .position(|n| *n == name)
            .or_else(|| {
                // tonic given in the other spelling
                let other = if table == &FLATS { &SHARPS } else { &FLATS };
                other.iter().position(|n| *n == name)
            })
