OPERATIONS = {
    "plus": lambda a, b: a + b,
    "minus": lambda a, b: a - b,
    "multiplied by": lambda a, b: a * b,
    "divided by": lambda a, b: a // b if a * b >= 0 or a % b == 0 else -(-a // b),
    "times": lambda a, b: a * b,
}


def _is_int(token):
    try:
        int(token)
        return True
    except ValueError:
        return False


def answer(question):
    if not question.startswith("What is") or not question.endswith("?"):
        raise ValueError("unknown operation")
    body = question[len("What is"):-1].strip()
    body = body.replace("multiplied by", "multiplied_by").replace("divided by", "divided_by")
    tokens = [t.replace("_", " ") for t in body.split()]
    if not tokens:
        raise ValueError("syntax error")

    # Validate tokens: anything not a number or known op is unknown
    for tok in tokens:
        if not _is_int(tok) and tok not in OPERATIONS:
            raise ValueError("unknown operation")

    if not _is_int(tokens[0]):
        raise ValueError("syntax error")
    result = int(tokens[0])
    i = 1
    while i < len(tokens):
        op = tokens[i]
        if op not in OPERATIONS:
            raise ValueError("syntax error")
        if i + 1 >= len(tokens) or not _is_int(tokens[i + 1]):
            raise ValueError("syntax error")
        operand = int(tokens[i + 1])
        if op == "divided by":
            if operand == 0:
                raise ValueError("syntax error")
            q = abs(result) // abs(operand)
            result = q if (result >= 0) == (operand >= 0) else -q
        else:
            result = OPERATIONS[op](result, operand)
        i += 2
    return result
