import java.util.ArrayList;
import java.util.List;

class Dominoes {

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        if (inputDominoes == null || inputDominoes.isEmpty()) {
            return new ArrayList<>();
        }

        int n = inputDominoes.size();
        boolean[] used = new boolean[n];
        List<Domino> chain = new ArrayList<>();

        Domino first = inputDominoes.get(0);
        used[0] = true;
        chain.add(first);

        if (search(inputDominoes, used, chain, first.getLeft(), first.getRight(), 1)) {
            return chain;
        }

        throw new ChainNotFoundException("No domino chain found.");
    }

    private boolean search(List<Domino> dominoes, boolean[] used, List<Domino> chain,
                           int start, int end, int count) {
        if (count == dominoes.size()) {
            return start == end;
        }

        for (int i = 0; i < dominoes.size(); i++) {
            if (used[i]) {
                continue;
            }
            Domino d = dominoes.get(i);

            if (d.getLeft() == end) {
                used[i] = true;
                chain.add(d);
                if (search(dominoes, used, chain, start, d.getRight(), count + 1)) {
                    return true;
                }
                chain.remove(chain.size() - 1);
                used[i] = false;
            }

            if (d.getRight() == end && d.getLeft() != d.getRight()) {
                used[i] = true;
                chain.add(new Domino(d.getRight(), d.getLeft()));
                if (search(dominoes, used, chain, start, d.getLeft(), count + 1)) {
                    return true;
                }
                chain.remove(chain.size() - 1);
                used[i] = false;
            }
        }

        return false;
    }

}
```

