//! An internal DSL, inspired by the Graphviz DOT language, for describing
//! graphs directly in Rust code using the builder pattern.

pub mod graph {
    use std::collections::HashMap;

    use self::graph_items::edge::Edge;
    use self::graph_items::node::Node;

    /// Merges `(key, value)` string pairs into an owned attribute map,
    /// overwriting the values of keys that are already present.
    ///
    /// This function is private to `graph`, but visible to its descendant
    /// modules, so graphs, nodes and edges all share the same attribute logic.
    fn merge_attrs(target: &mut HashMap<String, String>, attrs: &[(&str, &str)]) {
        target.extend(
            attrs
                .iter()
                .map(|&(key, value)| (key.to_string(), value.to_string())),
        );
    }

    /// A graph made of nodes, edges and graph-level attributes.
    #[derive(Debug, Default, Clone, PartialEq, Eq)]
    pub struct Graph {
        pub nodes: Vec<Node>,
        pub edges: Vec<Edge>,
        pub attrs: HashMap<String, String>,
    }

    impl Graph {
        /// Creates an empty graph: no nodes, no edges and no attributes.
        pub fn new() -> Self {
            Self::default()
        }

        /// Adds the given nodes to the graph.
        pub fn with_nodes(mut self, nodes: &[Node]) -> Self {
            self.nodes.extend_from_slice(nodes);
            self
        }

        /// Adds the given edges to the graph.
        pub fn with_edges(mut self, edges: &[Edge]) -> Self {
            self.edges.extend_from_slice(edges);
            self
        }

        /// Adds the given `(key, value)` attributes to the graph.
        pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
            merge_attrs(&mut self.attrs, attrs);
            self
        }

        /// Looks up a node by its name.
        pub fn node(&self, name: &str) -> Option<&Node> {
            self.nodes.iter().find(|node| node.name() == name)
        }

        /// Alias of [`Graph::node`], kept for `get_`-style naming compatibility.
        pub fn get_node(&self, name: &str) -> Option<&Node> {
            self.node(name)
        }

        /// Looks up a graph-level attribute by its key.
        pub fn attr(&self, key: &str) -> Option<&str> {
            self.attrs.get(key).map(String::as_str)
        }
    }

    pub mod graph_items {
        pub mod node {
            use std::collections::HashMap;

            use crate::graph::merge_attrs;

            /// A named node carrying arbitrary string attributes.
            #[derive(Debug, Clone, PartialEq, Eq)]
            pub struct Node {
                name: String,
                attrs: HashMap<String, String>,
            }

            impl Node {
                /// Creates a node with the given name and no attributes.
                pub fn new(name: &str) -> Self {
                    Self {
                        name: name.to_string(),
                        attrs: HashMap::new(),
                    }
                }

                /// Adds the given `(key, value)` attributes to the node.
                pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
                    merge_attrs(&mut self.attrs, attrs);
                    self
                }

                /// The node's name.
                pub fn name(&self) -> &str {
                    &self.name
                }

                /// Looks up an attribute of the node by its key.
                pub fn attr(&self, key: &str) -> Option<&str> {
                    self.attrs.get(key).map(String::as_str)
                }

                /// Alias of [`Node::attr`], kept for `get_`-style naming compatibility.
                pub fn get_attr(&self, key: &str) -> Option<&str> {
                    self.attr(key)
                }
            }
        }

        pub mod edge {
            use std::collections::HashMap;

            use crate::graph::merge_attrs;

            /// An edge between two nodes (by name), carrying arbitrary string attributes.
            #[derive(Debug, Clone, PartialEq, Eq)]
            pub struct Edge {
                source: String,
                target: String,
                attrs: HashMap<String, String>,
            }

            impl Edge {
                /// Creates an edge between the two named nodes, with no attributes.
                pub fn new(source: &str, target: &str) -> Self {
                    Self {
                        source: source.to_string(),
                        target: target.to_string(),
                        attrs: HashMap::new(),
                    }
                }

                /// Adds the given `(key, value)` attributes to the edge.
                pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
                    merge_attrs(&mut self.attrs, attrs);
                    self
                }

                /// The name of the node this edge starts from.
                pub fn source(&self) -> &str {
                    &self.source
                }

                /// The name of the node this edge goes to.
                pub fn target(&self) -> &str {
                    &self.target
                }

                /// Looks up an attribute of the edge by its key.
                pub fn attr(&self, key: &str) -> Option<&str> {
                    self.attrs.get(key).map(String::as_str)
                }

                /// Alias of [`Edge::attr`], kept for `get_`-style naming compatibility.
                pub fn get_attr(&self, key: &str) -> Option<&str> {
                    self.attr(key)
                }
            }
        }
    }
}
