// Sum of all divisors of n excluding n itself.
long long aliquot_sum(long long n) {
    if (n == 1) {
        return 0;
    }

    long long sum = 1;  // 1 divides every n > 1
    for (long long i = 2; i * i <= n; ++i) {
        if (n % i == 0) {
            sum += i;
            const long long paired = n / i;
            if (paired != i) {
                sum += paired;
            }
        }
    }
    return sum;
}

}  // namespace

classification classify(int n) {
    if (n <= 0) {
        throw std::domain_error(
            "Classification is only possible for positive integers.");
    }

    const long long value = n;
    const long long sum = aliquot_sum(value);

    if (sum == value) {
        return classification::perfect;
    }
    if (sum > value) {
        return classification::abundant;
    }
    return classification::deficient;
}

}  // namespace perfect_numbers
```

The tests expect each verse on **one line**, with its clauses separated by single spaces. For example, verse 2 is `This is the malt that lay in the house that Jack built.`. When there are several verses, they are joined with `"\n"`.

**Approach:**
- **Two arrays drive the rhyme:**
  - `SUBJECTS` holds the subject each verse introduces: house, malt, rat, and so on.
  - `ACTIONS` holds what each subject did to the one before it. `ACTIONS[i]` is what `SUBJECTS[i + 1]` did to `SUBJECTS[i]`.
- **`verse(n)`** starts with "This is the" plus the n‑th subject. It then walks back toward verse 1, adding " that <action> the <previous subject>" each step. It ends with a period.
- **`verses(start, end)`** builds each verse in the range and joins them with newlines.
- **`sing()`** returns all twelve verses.
- **Validation:** invalid verse numbers, or a start verse after the end verse, throw `IllegalArgumentException`.

src/main/java/House.java
```java
import java.util.stream.Collectors;
import java.util.stream.IntStream;

class House {

    // The subject introduced by each verse; SUBJECTS[0] belongs to verse 1.
    private static final String[] SUBJECTS = {
        "house that Jack built",
        "malt",
        "rat",
        "cat",
        "dog",
        "cow with the crumpled horn",
        "maiden all forlorn",
        "man all tattered and torn",
        "priest all shaven and shorn",
        "rooster that crowed in the morn",
        "farmer sowing his corn",
        "horse and the hound and the horn"
    };

    // ACTIONS[i] is what SUBJECTS[i + 1] did to SUBJECTS[i].
    private static final String[] ACTIONS = {
        "lay in",
        "ate",
        "killed",
        "worried",
        "tossed",
        "milked",
        "kissed",
        "married",
        "woke",
        "kept",
        "belonged to"
    };

    String verse(int verse) {
        if (verse < 1 || verse > SUBJECTS.length) {
            throw new IllegalArgumentException(
                "Verse must be between 1 and " + SUBJECTS.length + ", but was " + verse);
        }

        StringBuilder builder = new StringBuilder("This is the ").append(SUBJECTS[verse - 1]);
        for (int i = verse - 2; i >= 0; i--) {
            builder.append(" that ")
                   .append(ACTIONS[i])
                   .append(" the ")
                   .append(SUBJECTS[i]);
        }
        return builder.append('.').toString();
    }

    String verses(int startVerse, int endVerse) {
        if (startVerse > endVerse) {
            throw new IllegalArgumentException(
                "Start verse (" + startVerse + ") must not be after end verse (" + endVerse + ")");
        }
        return IntStream.rangeClosed(startVerse, endVerse)
                .mapToObj(this::verse)
                .collect(Collectors.joining("\n"));
    }

    String sing() {
        return verses(1, SUBJECTS.length);
    }

}
```

